window.getFurnaceIconHtml = (level, size = 32) => {
  if (!level || level === "N/A" || level === "" || level === "Unlinked" || level === "Pending Setup") {
    return `<span class="furnace-level-badge unlinked" title="Unlinked / Sync Setup Required" style="display:inline-flex; align-items:center; gap:5px; background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.12); padding:4px 10px; border-radius:10px; font-weight:600; font-size:${Math.max(11, Math.round(size*0.34))}px; color:var(--text-muted); white-space:nowrap; vertical-align:middle;"><span style="opacity:0.6;">⚠️</span> Unlinked</span>`;
  }
  
  const rawStr = level.toString().trim().toUpperCase();
  let fcNum = null;
  let furnaceNum = null;
  
  // 1. Check for explicit "FC", "FIRE CRYSTAL", or "STOVE_LV_" prefix followed by number 1-10
  const fcMatch = rawStr.match(/(?:FC|FIRE\s*CRYSTAL|STOVE_LV_)\s*[\.-]?\s*(\d+)/i);
  if (fcMatch) {
     const parsedFc = parseInt(fcMatch[1], 10);
     if (parsedFc >= 1 && parsedFc <= 10) {
        fcNum = parsedFc;
     } else if (parsedFc > 30 && parsedFc <= 40) {
        fcNum = parsedFc - 30;
     } else if (parsedFc > 40 && parsedFc <= 80) {
        fcNum = Math.ceil((parsedFc - 30) / 5);
     }
  } else {
     // 2. If no explicit FC prefix, extract the FIRST number in the string
     const firstNumMatch = rawStr.match(/(\d+)/);
     if (firstNumMatch) {
        const numVal = parseInt(firstNumMatch[1], 10);
        if (numVal > 30 && numVal <= 40) {
           fcNum = numVal - 30;
        } else if (numVal > 40 && numVal <= 80) {
           fcNum = Math.ceil((numVal - 30) / 5);
        } else if (numVal >= 1 && numVal <= 30) {
           furnaceNum = numVal;
        }
     }
  }

  // Render 3D Gem Faceted Fire Crystal Star Badge if fcNum is valid (FC 1 - 10)
  if (fcNum && fcNum >= 1 && fcNum <= 10) {
     const canvasDisplaySize = Math.round(size * 1.35);
     const marginOffset = Math.round((canvasDisplaySize - size) / 2);
     return `<canvas class="fc-unified-badge" data-fc="${fcNum}" data-size="${size}" style="display:inline-block; vertical-align:middle; width:${canvasDisplaySize}px; height:${canvasDisplaySize}px; cursor:pointer; user-select:none; -webkit-user-select:none; margin:-${marginOffset}px 2px; transition:all 0.25s ease;" title="Fire Crystal ${fcNum} (FC ${fcNum})"></canvas>`;
  }

  // Render Modern Standard Furnace Badge (Furnace 1 to 30)
  if (furnaceNum && furnaceNum >= 1 && furnaceNum <= 30) {
    const fontSize = Math.max(12, Math.round(size * 0.38));
    const padV = Math.max(3, Math.round(size * 0.08));
    const padH = Math.max(8, Math.round(size * 0.22));
    return `<span class="furnace-level-badge" title="Furnace Level ${furnaceNum}" style="display:inline-flex; align-items:center; justify-content:center; gap:6px; background:linear-gradient(135deg, rgba(249,115,22,0.25), rgba(15,23,42,0.95)); border:1.5px solid rgba(249,115,22,0.55); padding:${padV}px ${padH}px; border-radius:12px; font-weight:800; font-size:${fontSize}px; color:#ffffff; box-shadow:0 4px 14px rgba(249,115,22,0.25); white-space:nowrap; vertical-align:middle;">
      <span style="filter:drop-shadow(0 0 6px #f97316); font-size:${Math.round(fontSize*1.15)}px;">🔥</span> Lv ${furnaceNum}
    </span>`;
  }

  return `<span class="furnace-level-badge unlinked" title="Unlinked / Sync Setup Required" style="display:inline-flex; align-items:center; gap:5px; background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.12); padding:4px 10px; border-radius:10px; font-weight:600; font-size:${Math.max(11, Math.round(size*0.34))}px; color:var(--text-muted); white-space:nowrap; vertical-align:middle;"><span style="opacity:0.6;">⚠️</span> Unlinked</span>`;
};

window.getFurnaceNumericValue = (level) => {
  if (!level) return 0;
  const rawStr = level.toString().trim().toUpperCase();
  const fcMatch = rawStr.match(/(?:FC|FIRE\s*CRYSTAL|STOVE_LV_)\s*[\.-]?\s*(\d+)/i);
  if (fcMatch) {
     const parsedFc = parseInt(fcMatch[1], 10);
     if (parsedFc >= 1 && parsedFc <= 10) return 30 + parsedFc;
     if (parsedFc > 30 && parsedFc <= 40) return parsedFc;
     if (parsedFc > 40 && parsedFc <= 80) return 30 + Math.ceil((parsedFc - 30) / 5);
  }
  const firstNumMatch = rawStr.match(/(\d+)/);
  if (firstNumMatch) {
     const numVal = parseInt(firstNumMatch[1], 10);
     if (numVal > 30 && numVal <= 40) return numVal;
     if (numVal > 40 && numVal <= 80) return 30 + Math.ceil((numVal - 30) / 5);
     if (numVal >= 1 && numVal <= 30) return numVal;
  }
  return 0;
};

window.renderFurnaceSelectHtml = (id = 'manualFurnaceLevel', selectedVal = '', extraStyles = '') => {
  const norm = (selectedVal || '').toString().trim().toUpperCase();
  let selFc = null;
  let selLv = null;

  const fcMatch = norm.match(/(?:FC|FIRE\s*CRYSTAL|STOVE_LV_)\s*[\.-]?\s*(\d+)/i);
  if (fcMatch) {
     const pFc = parseInt(fcMatch[1], 10);
     if (pFc >= 1 && pFc <= 10) selFc = pFc;
     else if (pFc > 30 && pFc <= 40) selFc = pFc - 30;
     else if (pFc > 40 && pFc <= 80) selFc = Math.ceil((pFc - 30) / 5);
  } else {
     const firstNumMatch = norm.match(/(\d+)/);
     if (firstNumMatch) {
        const numVal = parseInt(firstNumMatch[1], 10);
        if (numVal > 30 && numVal <= 40) selFc = numVal - 30;
        else if (numVal > 40 && numVal <= 80) selFc = Math.ceil((numVal - 30) / 5);
        else if (numVal >= 1 && numVal <= 30) selLv = numVal;
     }
  }
  
  let options = `
    <option value="" ${(!selFc && !selLv) ? 'selected' : ''}>Select Furnace Level (Optional)</option>
    <optgroup label="🔥 Fire Crystal (FC) Levels">
  `;
  
  for (let fc = 10; fc >= 1; fc--) {
    const val = `FC ${fc}`;
    const isSel = (selFc === fc);
    options += `<option value="${val}" ${isSel ? 'selected' : ''}>FC ${fc} (Fire Crystal ${fc})</option>`;
  }
  
  options += `
    </optgroup>
    <optgroup label="🪵 Standard Furnace Levels">
  `;
  
  for (let lv = 30; lv >= 1; lv--) {
    const val = `${lv}`;
    const isSel = (!selFc && selLv === lv);
    options += `<option value="${val}" ${isSel ? 'selected' : ''}>Furnace ${lv}</option>`;
  }
  options += `</optgroup>`;

  return `<select id="${id}" style="width:100%; padding:10px 14px; border-radius:8px; border:1px solid var(--border); background:var(--bg-main); color:var(--text-main); font-size:15px; box-sizing:border-box; ${extraStyles}">${options}</select>`;
};

// --- Security Helpers ---
function escapeHTML(str) {
  if (typeof str !== 'string') str = String(str || '');
  return str.replace(/[&<>'"]/g, tag => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      "'": '&#39;',
      '"': '&quot;'
  }[tag]));
}
window.escapeHTML = escapeHTML;

window.translateWosApiError = (msg, code = null) => {
  if (typeof msg === 'object' && msg !== null) {
    if (msg.code !== undefined) code = msg.code;
    msg = msg.message || msg.rawMsg || JSON.stringify(msg);
  }
  let cleanMsg = (msg || '').toString().trim();
  
  // Extract code from message if embedded (e.g. "[Code 15030]")
  const extractedCodeMatch = cleanMsg.match(/\[Code\s*(\d+)\]/i);
  if (!code && extractedCodeMatch) {
    code = extractedCodeMatch[1];
  }
  // Strip duplicate code badges from raw text
  cleanMsg = cleanMsg.replace(/\[Code\s*\d+\]\s*/gi, '').trim();

  const codeNum = typeof code === 'number' ? code : (code ? parseInt(code, 10) : null);
  const codeBadge = codeNum ? `[Code ${codeNum}] ` : '';

  if (codeNum === 15030 || codeNum === 101031008 || codeNum === 15006 || cleanMsg.includes("未登录") || cleanMsg.includes("登录态已失效") || cleanMsg.includes("已失效") || cleanMsg.includes("token失效")) {
    return `${codeBadge}30-Day session token expired. Please enter a fresh in-game code to renew.`;
  }
  if (codeNum === 101031005 || cleanMsg.includes("验证码发送次数已达上限") || cleanMsg.includes("次数已达上限") || cleanMsg.includes("上限")) {
    return `${codeBadge}Daily verification code limit reached for this Game ID today. Please wait a while before requesting another code, or enter Chief Name manually.`;
  }
  if (codeNum === 101031002 || cleanMsg.includes("验证码错误") || cleanMsg.includes("验证码无效") || cleanMsg.includes("验证码已过期")) {
    return `${codeBadge}Invalid or expired verification code. Please check your in-game mailbox or request a new code.`;
  }
  if (codeNum === 101031001 || cleanMsg.includes("角色不存在") || cleanMsg.includes("用户不存在") || cleanMsg.includes("未找到")) {
    return `${codeBadge}Player ID not found. Please double-check your numeric Game ID in Whiteout Survival.`;
  }
  if (codeNum === 40001 || codeNum === 40003 || cleanMsg.includes("频繁") || cleanMsg.includes("稍后再试")) {
    return `${codeBadge}Too many requests. Please wait a moment and try again.`;
  }
  if (cleanMsg.includes("参数错误")) {
    return `${codeBadge}Invalid request parameters. Please verify your Game ID.`;
  }
  if (cleanMsg.includes("系统错误") || cleanMsg.includes("服务异常")) {
    return `${codeBadge}Game server is currently busy. Please try again shortly.`;
  }

  // Catch-all for any untranslated Chinese characters
  if (/[\u4e00-\u9fa5]/.test(cleanMsg)) {
    return `${codeBadge}30-Day session expired or profile unavailable. Please verify with a fresh in-game code.`;
  }

  if (!cleanMsg) return `${codeBadge}An error occurred communicating with the game server.`;
  return codeBadge ? `${codeBadge}${cleanMsg}` : cleanMsg;
};

window.parseDateSafe = (dateInput) => {
    if (!dateInput) return null;
    if (dateInput instanceof Date) return isNaN(dateInput.getTime()) ? null : dateInput;
    try {
        const str = dateInput.toString().trim();
        if (!str) return null;
        const norm = str.includes('T') ? str : str.replace(/-/g, '/');
        const d = new Date(norm);
        return isNaN(d.getTime()) ? null : d;
    } catch(e) {
        return null;
    }
};

window.formatDateForDisplay = (dateInput) => {
    if (!dateInput) return 'N/A';
    try {
        const d = window.parseDateSafe ? window.parseDateSafe(dateInput) : new Date(dateInput);
        if (!d || isNaN(d.getTime())) return String(dateInput);
        return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    } catch (e) {
        return String(dateInput || 'N/A');
    }
};

window.calculateTimeActive = (dateInput) => {
   if (!dateInput) return 'Unknown';
   const startDate = window.parseDateSafe ? window.parseDateSafe(dateInput) : new Date(dateInput);
   if (!startDate) {
       return window.formatTimeActiveShort(dateInput.toString());
   }
   
   const now = new Date();
   let years = now.getFullYear() - startDate.getFullYear();
   let months = now.getMonth() - startDate.getMonth();
   let days = now.getDate() - startDate.getDate();
   
   if (days < 0) {
      months--;
      const prevMonthLastDay = new Date(now.getFullYear(), now.getMonth(), 0).getDate();
      days += prevMonthLastDay;
   }
   if (months < 0) {
      years--;
      months += 12;
   }
   
   if (years < 0) return '0d';
   
   let parts = [];
   if (years > 0) parts.push(`${years}y`);
   if (months > 0) parts.push(`${months}m`);
   if (days > 0 || parts.length === 0) parts.push(`${days}d`);
   
   return parts.join(' ');
};

window.formatTimeActiveShort = (str) => {
    if (!str) return 'Unknown';
    if (typeof str !== 'string') str = String(str);
    str = str.trim();
    if (!str) return 'Unknown';
    
    // If input is a raw date string (e.g. '2024/11/18', '2024-11-18', '11/18/2024', ISO date), calculate elapsed active time
    if (!/\b(years?|months?|days?|y|m|d)\b/i.test(str)) {
        const parsedD = window.parseDateSafe ? window.parseDateSafe(str) : new Date(str);
        if (parsedD && !isNaN(parsedD.getTime())) return window.calculateTimeActive(str);
    }

    let formatted = str.replace(/\s*years?/gi, 'y')
              .replace(/\s*months?/gi, 'm')
              .replace(/\s*days?/gi, 'd')
              .replace(/,\s*/g, ' ')
              .replace(/\s+/g, ' ')
              .trim();
              
    let filtered = formatted.split(' ').filter(part => !part.match(/^0[ymd]$/i)).join(' ');
    return filtered === '' ? '0d' : filtered;
};

window.formatDateForInput = (dateStr) => {
   if (!dateStr) return '';
   const d = window.parseDateSafe ? window.parseDateSafe(dateStr) : new Date(dateStr);
   if (!d || isNaN(d.getTime())) return '';
   const year = d.getFullYear();
   const month = String(d.getMonth() + 1).padStart(2, '0');
   const day = String(d.getDate()).padStart(2, '0');
   return `${year}-${month}-${day}`;
};


// --- Settings Sidebar Logic ---
const settingsBtn = document.getElementById('settingsBtn');
const closeSidebar = document.getElementById('closeSidebar');
const settingsSidebar = document.getElementById('settingsSidebar');
const sidebarOverlay = document.getElementById('sidebarOverlay');

const openSidebar = () => {
  // Force close any open autocomplete dropdowns to fix Apple/Safari bug
  document.querySelectorAll('.custom-autocomplete-dropdown').forEach(d => d.style.display = 'none');
  if(settingsSidebar) settingsSidebar.classList.add('open');
  if(sidebarOverlay) sidebarOverlay.classList.add('active');
  document.body.classList.add('sidebar-open');
  document.documentElement.classList.add('sidebar-open');
};

const closeSidebarFunc = () => {
  if(settingsSidebar) settingsSidebar.classList.remove('open');
  if(sidebarOverlay) sidebarOverlay.classList.remove('active');
  document.body.classList.remove('sidebar-open');
  document.documentElement.classList.remove('sidebar-open');
};

window.openSidebar = openSidebar;
window.closeSidebarFunc = closeSidebarFunc;

const mobileSettingsBtn = document.getElementById('mobileSettingsBtn');
if(mobileSettingsBtn) mobileSettingsBtn.addEventListener('click', () => {
  openSidebar();
  if(mobileMenu) {
    mobileMenu.classList.remove('open');
    document.body.classList.remove('mobile-menu-open');
    document.documentElement.classList.remove('mobile-menu-open');
  }
});

if(settingsBtn) settingsBtn.addEventListener('click', openSidebar);
if(closeSidebar) closeSidebar.addEventListener('click', closeSidebarFunc);
if(sidebarOverlay) {
  sidebarOverlay.addEventListener('click', closeSidebarFunc);
  // Prevent iOS touchmove propagation to background body
  sidebarOverlay.addEventListener('touchmove', (e) => {
    e.preventDefault();
  }, { passive: false });
}

// --- Mobile Menu Logic ---
const mobileMenuBtn = document.getElementById('mobileMenuBtn');
const mobileMenu = document.getElementById('mobileMenu');

if(mobileMenuBtn) {
  mobileMenuBtn.addEventListener('click', () => {
    // Force close any open autocomplete dropdowns
    document.querySelectorAll('.custom-autocomplete-dropdown').forEach(d => d.style.display = 'none');
    if(mobileMenu) {
      const willOpen = !mobileMenu.classList.contains('open');
      mobileMenu.classList.toggle('open');
      if (willOpen) {
        document.body.classList.add('mobile-menu-open');
        document.documentElement.classList.add('mobile-menu-open');
      } else {
        document.body.classList.remove('mobile-menu-open');
        document.documentElement.classList.remove('mobile-menu-open');
      }
    }
  });
}

// --- Theme Logic ---
const updateMetaThemeColor = (theme) => {
  let metaTheme = document.querySelector('meta[name="theme-color"]');
  if (!metaTheme) {
    metaTheme = document.createElement('meta');
    metaTheme.name = 'theme-color';
    document.head.appendChild(metaTheme);
  }
  let color = '#0f172a'; // midnight / default
  if (theme === 'ombre') color = '#0b051a'; // diva dark purple
  else if (theme === 'light') color = '#ffffff';
  metaTheme.setAttribute('content', color);
};

const initTheme = () => {
  const savedTheme = localStorage.getItem('theme') || 'midnight';
  document.documentElement.setAttribute('data-theme', savedTheme);
  updateMetaThemeColor(savedTheme);
  
  // Highlight the active card
  document.querySelectorAll('.theme-card').forEach(card => {
    if (card.getAttribute('data-theme') === savedTheme) {
      card.classList.add('active');
    } else {
      card.classList.remove('active');
    }
  });
};

document.querySelectorAll('.theme-card').forEach(card => {
  card.addEventListener('click', () => {
    if(!card) return;
    
    const theme = card.getAttribute('data-theme');
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('theme', theme);
    updateMetaThemeColor(theme);
    
    // Update active card
    document.querySelectorAll('.theme-card').forEach(c => c.classList.remove('active'));
    card.classList.add('active');
    
    // Auto-close sidebar to see changes
    closeSidebarFunc();
  });
});

initTheme();

