// Fetch all Gift Code enrollments natively from Firebase Realtime Database
window.fetchGiftcodeEnrollments = async () => {
    if (window.giftcodeCache) return window.giftcodeCache;
    try {
        const snap = await get(ref(db, 'giftcode_bot'));
        if (snap.exists()) {
            window.giftcodeCache = snap.val();
            if (window.giftcodeCache) {
                Object.values(window.giftcodeCache).forEach(rec => {
                    if (rec && rec.gameId && rec.enrolled !== false) {
                        enrolledGameIds.add(rec.gameId.toString().trim());
                    }
                });
            }
            return window.giftcodeCache;
        }
    } catch(e) { console.warn('Firebase giftcode_bot read error:', e); }

    // Seed from Google Sheets if Firebase node is empty
    let seededData = {};
    try {
        const gcb = await fetchSheet("giftcodebot");
        if (gcb && gcb.length > 1) {
            for (let i = 1; i < gcb.length; i++) {
                let name = gcb[i][1];
                let id = gcb[i][2] ? gcb[i][2].toString().trim() : '';
                if (id) {
                    enrolledGameIds.add(id);
                    seededData[id] = {
                        gameId: id,
                        name: name || '',
                        enrolled: true,
                        status: 'Active',
                        timestamp: Date.now()
                    };
                }
            }
            try { await set(ref(db, 'giftcode_bot'), seededData); } catch(e) { console.error(e); }
        }
    } catch(e) { console.error(e); }
    
    window.giftcodeCache = seededData;
    return seededData;
};

// Check if a player is enrolled in Gift Code Bot
window.isGiftcodeEnrolled = async (gameId) => {
    if (!gameId) return false;
    const gIdStr = gameId.toString().trim();
    if (window.enrolledGameIds && window.enrolledGameIds.has(gIdStr)) return true;
    if (typeof enrolledGameIds !== 'undefined' && enrolledGameIds && enrolledGameIds.has(gIdStr)) return true;
    const allEnrollments = await window.fetchGiftcodeEnrollments();
    if (allEnrollments && allEnrollments[gIdStr] && allEnrollments[gIdStr].enrolled) {
        if (window.enrolledGameIds) window.enrolledGameIds.add(gIdStr);
        return true;
    }
    return (window.enrolledGameIds ? window.enrolledGameIds.has(gIdStr) : false);
};

// Enroll a player natively into Firebase Realtime Database
window.enrollGiftcodeBot = async (gameId, chiefName, isAlt = false, ownerUid = null) => {
    if (!gameId) return false;
    const gIdStr = gameId.toString().trim();
    const record = {
        gameId: gIdStr,
        name: chiefName || '',
        enrolled: true,
        status: 'Active',
        isAlt: !!isAlt,
        ownerUid: ownerUid || null,
        timestamp: Date.now()
    };
    
    try {
        await set(ref(db, `giftcode_bot/${gIdStr}`), record);
        if (window.giftcodeCache) {
            window.giftcodeCache[gIdStr] = record;
        }
        if (window.enrolledGameIds) window.enrolledGameIds.add(gIdStr);
        if (typeof enrolledGameIds !== 'undefined' && enrolledGameIds) enrolledGameIds.add(gIdStr);
        return true;
    } catch(e) {
        console.warn("Failed to write giftcode_bot in Firebase", e);
        return false;
    }
};

// Seamless Auto-Sync: Guarantees 100% of claimed profiles & linked alts are enrolled in giftcode_bot
window.syncAllClaimedUsersToGiftbot = async () => {
    try {
        const usersSnap = await get(ref(db, 'users'));
        if (!usersSnap.exists()) return 0;
        const usersData = usersSnap.val() || {};
        let syncCount = 0;
        const updates = {};

        for (const [uid, u] of Object.entries(usersData)) {
            if (!u) continue;
            // Primary Main Character
            if (u.gameId) {
                const mainGid = String(u.gameId).trim();
                if (mainGid && /^\d+$/.test(mainGid)) {
                    updates[`giftcode_bot/${mainGid}`] = {
                        gameId: mainGid,
                        name: u.name || u.chiefName || (window.idToNameMap && window.idToNameMap[mainGid]) || '',
                        enrolled: true,
                        status: 'Active',
                        ownerUid: uid,
                        isAlt: false,
                        timestamp: Date.now()
                    };
                    syncCount++;
                }
            }
            // Linked Alt Characters
            if (u.linkedGameIds && Array.isArray(u.linkedGameIds)) {
                for (const agid of u.linkedGameIds) {
                    const altGid = String(agid).trim();
                    if (altGid && /^\d+$/.test(altGid)) {
                        const altTok = (u.altTokens && u.altTokens[altGid]) || {};
                        const altName = altTok.nickname || (window.idToNameMap && window.idToNameMap[altGid]) || `Alt ${altGid}`;
                        updates[`giftcode_bot/${altGid}`] = {
                            gameId: altGid,
                            name: altName,
                            enrolled: true,
                            status: 'Active',
                            ownerUid: uid,
                            isAlt: true,
                            timestamp: Date.now()
                        };
                        syncCount++;
                    }
                }
            }
        }

        if (Object.keys(updates).length > 0) {
            await update(ref(db), updates);
        }
        return syncCount;
    } catch(e) {
        console.warn("Auto-sync claimed users to giftcode_bot failed:", e);
        return 0;
    }
};

