window.toggleFrostCheckbox = async function(idx, field) {
  const alt = window.frostState.alts[idx];
  if (!alt) return;
  const newVal = !alt[field];
  alt[field] = newVal; // Optimistic update
  
  window.renderFrostClan();
  
  try {
    // Instant Firebase RTDB write (<50ms)
    await update(ref(db, `frost_clan/alts/${idx}`), { [field]: newVal, lastUpdated: Date.now() });
    try { localStorage.setItem('cached_frost_clan_alts', JSON.stringify(window.frostState.alts)); } catch(e) {}
  } catch (e) {
    console.error("Error saving frost checkbox:", e);
    window.showToast("Failed to save to database!", "error");
    alt[field] = !newVal; // Revert
    window.renderFrostClan();
  }
};

window.shieldAllFrostClan = async function() {
  const confirmed = await window.customConfirm("🛡️ Shield ALL Frost Clan Alts?\n\nThis will mark all alts as SHIELDED in Firebase.");
  if (!confirmed) return;

  const updatedAlts = window.frostState.alts.map(alt => ({ ...alt, shields: true }));
  window.frostState.alts = updatedAlts;
  window.renderFrostClan();

  window.showToast("🛡️ Shielding all Frost Clan alts in Firebase...", "success");
  try {
    await set(ref(db, 'frost_clan/alts'), updatedAlts);
    try { localStorage.setItem('cached_frost_clan_alts', JSON.stringify(updatedAlts)); } catch(e) {}
    if (window.showToast) window.showToast("✅ All Frost Clan alts marked as SHIELDED!", "success");
  } catch(e) {
    console.error("Bulk shield error:", e);
  }
};

window.resetFrostClan = async function() {
  const confirmed = await window.customConfirm("Are you sure you want to uncheck all Shields, Rebirth Tomes, and Daily Showdown for Frost Clan?");
  if (!confirmed) return;
  
  const resetAlts = window.frostState.alts.map(alt => ({
    ...alt,
    shields: false,
    rebirth: false,
    showdown: false
  }));
  window.frostState.alts = resetAlts;
  window.renderFrostClan();
  
  window.showToast("Resetting Frost Clan status in Firebase...", "info");
  try {
    await set(ref(db, 'frost_clan/alts'), resetAlts);
    try { localStorage.setItem('cached_frost_clan_alts', JSON.stringify(resetAlts)); } catch(e) {}
    if (window.showToast) window.showToast("✅ Frost Clan Reset successful!", "success");
  } catch (e) {
    console.error("Reset error:", e);
    window.showToast("Failed to reset in Firebase!", "error");
  }
};

// Fetch Championship Data natively from single master node activity_live
// Fetch Championship Data natively from master node activity_live with fallback to championship node
window.fetchChampionshipData = async () => {
    if (window.championshipCache) return window.championshipCache;
    const result = {};
    const isT = (v) => v === true || v === 'true' || v === 'yes' || v === 'YES' || v === 1;

    try {
        const snap = await get(ref(db, 'activity_live'));
        if (snap && snap.exists()) {
            const actObj = snap.val() || {};
            if (typeof actObj === 'object') {
                Object.entries(actObj).forEach(([gid, rec]) => {
                    if (rec && typeof rec === 'object') {
                        const chiefName = rec.name || (window.idToNameMap && window.idToNameMap[gid]) || 'Chief';
                        const isSigned = rec.championship !== undefined ? isT(rec.championship) : false;
                        result[gid] = {
                            gameId: gid,
                            name: chiefName,
                            signedUp: isSigned,
                            lastUpdated: rec.updatedAt || Date.now()
                        };
                    }
                });
            }
        }
    } catch(e) { console.warn("Firebase activity_live championship read error:", e); }

    // Fallback only for gameIds that do not exist at all in activity_live
    try {
        const champSnap = await get(ref(db, 'championship')).catch(() => null);
        if (champSnap && champSnap.exists()) {
            const champObj = champSnap.val() || {};
            if (typeof champObj === 'object') {
                Object.entries(champObj).forEach(([gid, rec]) => {
                    if (rec && typeof rec === 'object' && result[gid] === undefined) {
                        const chiefName = rec.name || (window.idToNameMap && window.idToNameMap[gid]) || 'Chief';
                        const isSigned = rec.signedUp !== undefined ? isT(rec.signedUp) : false;
                        result[gid] = {
                            gameId: gid,
                            name: chiefName,
                            signedUp: isSigned,
                            lastUpdated: rec.lastUpdated || rec.updatedAt || Date.now()
                        };
                    }
                });
            }
        }
    } catch(e) {}

    // Ensure all roster players are represented
    if (window.idToNameMap) {
        Object.entries(window.idToNameMap).forEach(([gid, name]) => {
            if (!result[gid]) {
                result[gid] = { gameId: gid, name: name, signedUp: false, lastUpdated: Date.now() };
            }
        });
    }

    window.championshipCache = result;
    return result;
};

// Toggle Championship signup status natively in master node activity_live & championship node
window.toggleChampionshipStatus = async (gameId, forceStatus = null) => {
    if (!gameId) return false;
    const gIdStr = gameId.toString().trim();
    let data = {};
    try { data = await window.fetchChampionshipData(); } catch(e) { console.error(e); }

    const isT = (v) => v === true || v === 'true' || v === 'yes' || v === 'YES' || v === 1;
    const existing = data[gIdStr] || { gameId: gIdStr, name: (window.idToNameMap && window.idToNameMap[gIdStr]) || 'Chief', signedUp: false };
    const currentStatus = isT(existing.signedUp);
    const newSignedUpStatus = (forceStatus !== null) ? Boolean(forceStatus) : !currentStatus;
    const adminName = currentUser ? ((window.idToNameMap && window.idToNameMap[currentUser.gameId]) || currentUser.name || "Admin") : "Admin";
    const playerName = existing.name || (window.idToNameMap && window.idToNameMap[gIdStr]) || 'Chief';
    const now = Date.now();
    const nameKey = playerName ? playerName.toLowerCase().replace(/[^a-z0-9]/g, '_') : '';

    try {
        // 1. Write directly to master node activity_live
        try {
            await update(ref(db, `activity_live/${gIdStr}`), {
                name: playerName,
                championship: newSignedUpStatus,
                updatedAt: now
            });
        } catch(uErr) {
            const snap = await get(ref(db, `activity_live/${gIdStr}`));
            const currentRec = (snap && snap.exists()) ? snap.val() : { name: playerName };
            currentRec.name = playerName;
            currentRec.championship = newSignedUpStatus;
            currentRec.updatedAt = now;
            await set(ref(db, `activity_live/${gIdStr}`), currentRec);
        }

        if (nameKey && nameKey !== gIdStr) {
            try {
                await update(ref(db, `activity_live/${nameKey}`), {
                    name: playerName,
                    championship: newSignedUpStatus,
                    updatedAt: now
                }).catch(() => null);
            } catch(e) {}
        }

        // 2. Secondary write for legacy node
        try {
            await set(ref(db, `championship/${gIdStr}`), {
                gameId: gIdStr, name: playerName, signedUp: newSignedUpStatus, lastUpdated: now, updatedBy: adminName
            });
            if (nameKey && nameKey !== gIdStr) {
                await set(ref(db, `championship/${nameKey}`), {
                    gameId: gIdStr, name: playerName, signedUp: newSignedUpStatus, lastUpdated: now, updatedBy: adminName
                }).catch(() => null);
            }
        } catch(e) {}

        // Update memory cache immediately
        if (window.championshipCache) {
            if (window.championshipCache[gIdStr]) {
                window.championshipCache[gIdStr].signedUp = newSignedUpStatus;
                window.championshipCache[gIdStr].lastUpdated = now;
            }
            if (nameKey && window.championshipCache[nameKey]) {
                window.championshipCache[nameKey].signedUp = newSignedUpStatus;
                window.championshipCache[nameKey].lastUpdated = now;
            }
        }

        window.clearAllEventCaches();

        try {
            if (window.logAdminAction) {
                window.logAdminAction("Championship Signup Toggle", `Toggled ${playerName} (${gIdStr}) to ${newSignedUpStatus ? 'YES (✅)' : 'NO (❌)'}`, playerName);
            }
        } catch(e) {}
        
        try {
            const evToken = await getAuthToken().catch(() => '');
            const url = `${API_BASE_URL}?api=updateEvent&name=${encodeURIComponent(playerName)}&eventName=${encodeURIComponent("Alliance Championship")}&status=${encodeURIComponent(newSignedUpStatus ? 'yes' : 'no')}&admin=${encodeURIComponent(adminName)}&token=${encodeURIComponent(evToken)}`;
            fetch(url, { mode: 'no-cors' }).catch(() => null);
        } catch(e) {}

        return true;
    } catch(e) {
        console.error("Failed to toggle championship status in Firebase:", e);
        return false;
    }
};

