window.adminUnlinkAltAccountPrompt = async (chiefName, altId) => {
    if (!(await window.customConfirm(`Are you sure you want to unlink ${altId} from ${chiefName}?`))) return;
    
    const gameId = window.nameToIdMap[chiefName];
    if (!gameId) {
        if(window.showToast) window.showToast("Could not find Game ID for " + chiefName, "error");
        else window.showToast("Could not find Game ID", "error");
        return;
    }
    
    try {
        const usersSnap = await get(ref(db, 'users'));
        const users = usersSnap.val() || {};
        let targetUid = null;
        let currentLinks = [];
        
        for (const [uid, u] of Object.entries(users)) {
            if (Number(u.gameId) === Number(gameId)) {
                targetUid = uid;
                currentLinks = u.linkedGameIds || [];
                break;
            }
        }
        
        if (!targetUid) {
            if(window.showToast) window.showToast("User is not registered on the site.", "error");
            return;
        }
        
        currentLinks = currentLinks.filter(id => id.toString().trim() !== altId.toString().trim());
        await set(ref(db, `users/${targetUid}/linkedGameIds`), currentLinks);
        
        if (window.showToast) window.showToast(`Unlinked ${altId} from ${chiefName}!`, "success");
        if (window.searchPlayerFull) window.searchPlayerFull(chiefName);
    } catch(e) {
        window.showToast(e.message, "error");
    }
};

window.adminLinkAltAccountPromptByChief = async (chiefName) => {
    const gameId = window.nameToIdMap[chiefName];
    if (!gameId) {
        if(window.showToast) window.showToast("Could not find Game ID for " + chiefName, "error");
        else window.showToast("Could not find Game ID", "error");
        return;
    }
    
    const altId = await window.customPrompt(`Enter the Game ID of the Alt Account you want to link to ${chiefName}:`);
    if (!altId || altId.trim() === '') return;
    
    try {
        const res = await fetch(`${API_BASE_URL}?api=adminLinkAlt&gameId=${encodeURIComponent(gameId)}&chiefName=${encodeURIComponent(chiefName)}&altGameId=${encodeURIComponent(altId.trim())}`);
        const json = await res.json();
        
        if (json.success) {
            if (window.showToast) window.showToast(`Alt Account linked for ${chiefName}!`, "success");
            if (document.getElementById('adminHubView')) window.views.admin();
            window.searchPlayerFull(chiefName);
        } else {
            window.customAlert(json.message || "Failed to link alt account.");
        }
    } catch(e) {
        window.showToast(e.message, "error");
    }
};

window.adminManageAltsPrompt = async (uid) => {
    try {
        const uSnap = await get(ref(db, `users/${uid}`));
        const u = uSnap.val();
        if (!u) return;
        const cName = idToNameMap[u.gameId] || u.name || "Chief";
        await window.adminLinkAltAccountPromptByChief(cName);
    } catch(e) {
        if (window.showToast) window.showToast(e.message, "error");
    }
};

window.openAdminEditFurnaceModal = async (chiefName, gameId = '', currentFurnace = '30') => {
  if (!window.isAdminUser(currentUser)) {
    if (window.showToast) window.showToast("Access Denied: Staff permissions required.", "error");
    return;
  }

  const oldModal = document.getElementById('adminEditFurnaceModalOverlay');
  if (oldModal && oldModal.parentNode) oldModal.parentNode.removeChild(oldModal);

  const modalOverlay = document.createElement('div');
  modalOverlay.id = 'adminEditFurnaceModalOverlay';
  modalOverlay.style.cssText = 'position:fixed; inset:0; background:rgba(15,23,42,0.85); backdrop-filter:blur(10px); z-index:99999; display:flex; align-items:center; justify-content:center; animation:fadeIn 0.2s ease;';

  const furnaceSelectHtml = window.renderFurnaceSelectHtml('adminEditFurnaceSelect', currentFurnace, 'margin-top:6px;');

  modalOverlay.innerHTML = `
    <div class="card" style="width:90%; max-width:480px; background:linear-gradient(145deg, rgba(15,23,42,0.95), rgba(30,41,59,0.9)); border:1px solid rgba(56,189,248,0.3); padding:28px; border-radius:20px; box-shadow:0 20px 50px rgba(0,0,0,0.6); text-align:left; animation:zoomIn 0.2s forwards;">
       <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:18px; border-bottom:1px solid rgba(255,255,255,0.1); padding-bottom:12px;">
          <h3 style="margin:0; color:#fff; font-size:20px; font-weight:800; display:flex; align-items:center; gap:8px;">🔥 Set Furnace Level</h3>
          <button id="closeAdminEditFurnaceBtn" style="background:none; border:none; color:var(--text-muted); font-size:28px; cursor:pointer; line-height:1;">&times;</button>
       </div>

       <div style="font-size:14px; color:#94a3b8; margin-bottom:16px;">
          Editing Chief: <strong style="color:#fff;">${window.escapeHTML(chiefName)}</strong> ${gameId ? `<span style="font-family:monospace; font-size:12px; color:var(--accent);">(${gameId})</span>` : ''}
       </div>

       <div style="display:flex; flex-direction:column; gap:18px;">
          <div>
             <label style="display:block; font-size:12px; font-weight:bold; color:#cbd5e1; margin-bottom:6px; text-transform:uppercase; letter-spacing:0.5px;">🔥 Select New Furnace / FC Level</label>
             <div style="display:flex; gap:14px; align-items:center;">
                <div style="flex:1;">
                   ${furnaceSelectHtml}
                </div>
                <div id="adminEditBadgePreview" style="min-width:120px; height:120px; background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.1); border-radius:14px; display:flex; align-items:center; justify-content:center; flex-shrink:0; padding:4px;">
                   ${window.getFurnaceIconHtml(currentFurnace, 110)}
                </div>
             </div>
          </div>

          <div style="display:flex; gap:12px; margin-top:10px;">
             <button id="cancelAdminEditFurnaceBtn" style="flex:1; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.2); color:#cbd5e1; padding:12px; border-radius:10px; cursor:pointer; font-weight:bold; font-size:15px;">Cancel</button>
             <button id="saveAdminEditFurnaceBtn" style="flex:1; background:linear-gradient(135deg, #06b6d4, #3b82f6); color:#fff; border:none; padding:12px; border-radius:10px; cursor:pointer; font-weight:bold; font-size:15px; box-shadow:0 4px 15px rgba(6,182,212,0.4);">Save Level</button>
          </div>
       </div>
    </div>`;

  document.body.appendChild(modalOverlay);

  const fSelect = document.getElementById('adminEditFurnaceSelect');
  const bPreview = document.getElementById('adminEditBadgePreview');
  if (fSelect && bPreview) {
     fSelect.addEventListener('change', (e) => {
        bPreview.innerHTML = window.getFurnaceIconHtml(e.target.value, 76);
     });
  }

  const closeModal = () => { if (document.body.contains(modalOverlay)) document.body.removeChild(modalOverlay); };
  const closeBtn = document.getElementById('closeAdminEditFurnaceBtn');
  const cancelBtn = document.getElementById('cancelAdminEditFurnaceBtn');
  if (closeBtn) closeBtn.onclick = closeModal;
  if (cancelBtn) cancelBtn.onclick = closeModal;

  const saveBtn = document.getElementById('saveAdminEditFurnaceBtn');
  if (saveBtn) {
     saveBtn.onclick = async () => {
        const newFurnace = document.getElementById('adminEditFurnaceSelect').value || currentFurnace;
        saveBtn.disabled = true;
        saveBtn.textContent = 'Saving...';

        try {
           const cleanGid = (gameId || window.nameToIdMap[chiefName.toLowerCase()] || window.nameToIdMap[chiefName] || '').toString().trim();

           // 1. Invalidate rosterCache so any future query pulls fresh data
           window.rosterCache = null;

           // 2. Read & update roster_live in Firebase directly
           try {
              const rosterSnap = await get(ref(db, 'roster_live')).catch(() => null);
              let rosterObj = (rosterSnap && rosterSnap.exists()) ? rosterSnap.val() : {};

              let foundKey = null;
              for (const [rk, rv] of Object.entries(rosterObj)) {
                 if (rk.toLowerCase().trim() === chiefName.toLowerCase().trim() ||
                    (rv && rv.name && rv.name.toLowerCase().trim() === chiefName.toLowerCase().trim()) ||
                    (rv && rv.chiefName && rv.chiefName.toLowerCase().trim() === chiefName.toLowerCase().trim()) ||
                    (cleanGid && rv && rv.gameId && rv.gameId.toString().trim() === cleanGid)) {
                    foundKey = rk;
                    break;
                 }
              }
              const saveKey = foundKey || (cleanGid ? cleanGid : chiefName);
              const updatedEntry = {
                 ...(rosterObj[saveKey] || {}),
                 name: chiefName,
                 gameId: cleanGid,
                 furnaceLevel: newFurnace,
                 stove_lv: newFurnace,
                 updatedAt: Date.now()
              };

              rosterObj[saveKey] = updatedEntry;

              await set(ref(db, `roster_live/${saveKey}`), updatedEntry);
              if (cleanGid && cleanGid !== saveKey) {
                 await set(ref(db, `roster_live/${cleanGid}`), updatedEntry);
              }
              window.rosterCache = rosterObj;
           } catch(e) { console.warn("roster_live save error:", e); }

           // 3. Update users/ node in Firebase if user account exists (main or alt)
           try {
              const usersSnap = await get(ref(db, 'users'));
              if (usersSnap.exists()) {
                 const allUsers = usersSnap.val();
                 for (const [uid, uData] of Object.entries(allUsers)) {
                    const uGid = (uData.gameId || '').toString().trim();
                    const uName = (uData.name || uData.chiefName || '').toString().trim();
                    
                    // Check if this is the user's primary character
                    if ((cleanGid && uGid === cleanGid) || (chiefName && uName.toLowerCase() === chiefName.toLowerCase())) {
                       await update(ref(db, `users/${uid}`), {
                          stove_lv: newFurnace,
                          furnaceLevel: newFurnace,
                          updatedAt: new Date().toISOString()
                       });
                       if (currentUser && currentUser.uid === uid) {
                          currentUser.stove_lv = newFurnace;
                          currentUser.furnaceLevel = newFurnace;
                          try { localStorage.setItem('cached_current_user', JSON.stringify(currentUser)); } catch(e) {}
                       }
                       break;
                    }

                    // Check if this is an Alt account of this user
                    if (cleanGid && ((uData.linkedGameIds && uData.linkedGameIds.includes(cleanGid)) || (uData.linkedAltsData && uData.linkedAltsData[cleanGid]) || (uData.altTokens && uData.altTokens[cleanGid]))) {
                       const altUpdates = {};
                       altUpdates[`linkedAltsData/${cleanGid}/stove_lv`] = newFurnace;
                       altUpdates[`linkedAltsData/${cleanGid}/furnaceLevel`] = newFurnace;
                       altUpdates[`linkedAltsData/${cleanGid}/updatedAt`] = new Date().toISOString();
                       if (uData.altTokens && uData.altTokens[cleanGid]) {
                          altUpdates[`altTokens/${cleanGid}/stove_lv`] = newFurnace;
                          altUpdates[`altTokens/${cleanGid}/furnaceLevel`] = newFurnace;
                       }
                       await update(ref(db, `users/${uid}`), altUpdates).catch(() => null);
                       
                       if (currentUser && currentUser.uid === uid) {
                          currentUser.linkedAltsData = currentUser.linkedAltsData || {};
                          if (currentUser.linkedAltsData[cleanGid]) {
                             currentUser.linkedAltsData[cleanGid].stove_lv = newFurnace;
                             currentUser.linkedAltsData[cleanGid].furnaceLevel = newFurnace;
                          }
                          if (currentUser.altTokens && currentUser.altTokens[cleanGid]) {
                             currentUser.altTokens[cleanGid].stove_lv = newFurnace;
                             currentUser.altTokens[cleanGid].furnaceLevel = newFurnace;
                          }
                          try { localStorage.setItem('cached_current_user', JSON.stringify(currentUser)); } catch(e) {}
                       }
                       break;
                    }
                 }
              }
           } catch(e) { console.warn("Failed to update user node:", e); }

           // 4. Update users_alts/${cleanGid} node directly in Firebase
           if (cleanGid) {
              try {
                 await update(ref(db, `users_alts/${cleanGid}`), {
                    gameId: cleanGid,
                    name: chiefName,
                    stove_lv: newFurnace,
                    furnaceLevel: newFurnace,
                    updatedAt: new Date().toISOString()
                 }).catch(() => null);
              } catch(e) {}
           }

           // Sync with BDC Central Command Backend
           window.callBdcBackend('update_furnace', {
              gameId: cleanGid,
              name: chiefName,
              level: newFurnace
           }).catch(() => null);

           // 5. Update in-memory liveData Chief's List row if loaded
           if (window.liveData && window.liveData["Chief's List"]) {
              const cList = window.liveData["Chief's List"];
              for (let i = 1; i < cList.length; i++) {
                 if ((cleanGid && cList[i][1] && cList[i][1].toString().trim() === cleanGid) ||
                     (chiefName && cList[i][0] && cList[i][0].toString().toLowerCase().trim() === chiefName.toLowerCase())) {
                    cList[i][2] = newFurnace;
                    break;
                 }
              }
           }

           if (window.logAdminAction) {
              window.logAdminAction("Set Furnace Level", `Updated '${chiefName}' (ID: ${cleanGid}) furnace level to ${newFurnace}`, chiefName);
           }

           if (window.showToast) window.showToast(`Updated ${chiefName}'s Furnace Level to ${newFurnace}!`, "success");
           closeModal();

           // 5. Instantly refresh the player card modal if it's open on screen!
           if (document.getElementById('rosterLookupResult')) {
              window.searchPlayerFull(chiefName).catch(() => null);
           } else if (typeof window.activeViewFunc === 'function') {
              window.activeViewFunc();
           }
        } catch(err) {
           console.error("Save furnace error:", err);
           if (window.showToast) window.showToast("Error updating level.", "error");
           saveBtn.disabled = false;
           saveBtn.textContent = 'Save Level';
        }
     };
  }
};


window.getAdminLevel = (user) => {
    if (!user || !user.gameId) return false;
    if (Number(user.gameId) === 318843189) return "R5"; // Root admin
    const val = window.systemAdmins[user.gameId];
    if (val === true || val === "R5") return "R5"; // Legacy support defaults to R5
    if (val === "R4") return "R4";
    return false;
  };

window.isAdminUser = (user) => {
  return window.getAdminLevel(user) !== false;
};

window.isGoogleAuthVerified = async () => {
    if (!currentUser || !auth || !auth.currentUser) return false;
    try {
        // We must check the token claims to see how they signed in for THIS specific session
        // providerData just lists all linked accounts, which could allow a weak password to bypass security
        const idTokenResult = await auth.currentUser.getIdTokenResult();
        return idTokenResult.claims.firebase.sign_in_provider === 'google.com';
    } catch (e) {
        console.warn("Failed to get sign-in provider:", e);
        return false;
    }
};

