window._executeLogBearTrapWinner = async (name, trap) => {
    window.showToast("Crowning Winner...", "accent");
    try {
        const adminName = currentUser ? (idToNameMap[currentUser.gameId] || "Admin") : "Admin";
        const token = await getAuthToken();
        const url = `${API_BASE_URL}?api=addBearTrapEventWin&name=${encodeURIComponent(name)}&trap=${encodeURIComponent(trap)}&admin=${encodeURIComponent(adminName)}&token=${encodeURIComponent(token)}`;
        const res = await fetch(url).then(r => r.json());
        
        if (res && res.success) {
            await set(ref(db, `config/bearTrapWinners/${trap}`), {
                name: name,
                score: res.newTotal,
                timestamp: Date.now()
            });
            
            // Update Firebase beartrap_wins natively
            const winKey = name.toLowerCase().replace(/[^a-z0-9]/g, '_');
            const winRef = ref(db, `beartrap_wins/${winKey}`);
            const winSnap = await get(winRef);
            let winData = winSnap.val() || { name: name, bt1: 0, bt2: 0, total: 0 };
            if (String(trap) === '1') winData.bt1 = (winData.bt1 || 0) + 1;
            else if (String(trap) === '2') winData.bt2 = (winData.bt2 || 0) + 1;
            winData.total = (winData.bt1 || 0) + (winData.bt2 || 0);
            await set(winRef, winData);
            window.logAdminAction("Bear Trap Champion Crowned", `Crowned ${name} as Bear Trap ${trap} Winner (New Total: ${res.newTotal})`, name);

            window.showToast(`🏆 Successfully crowned ${name} as Champion! (New Total: ${res.newTotal})`, "success");
            window.searchPlayerFull(name); // Refresh UI
        } else {
            window.showToast(`Error: ${res ? res.message : 'Unknown backend error'}`, "error");
        }
    } catch (e) {
        window.showToast(`Network Error: ${e.message}`, "error");
    }
};

  window.adminDeleteUserRow = async (uid, name) => {
      return window.adminDeletePlayer(name, null, uid);
  };

  window.adminDeletePlayer = async (name, passedGid = null, passedUid = null) => {
    let confirmDelete = await window.customConfirm(`⚠️ WARNING: DELETE PLAYER ⚠️\n\nAre you sure you want to COMPLETELY DELETE ${name || 'this character'}?\n\nThis will remove them from the live alliance roster, wipe player records, and permanently remove account data from the database.\n\nThis action cannot be undone.`);
    if (!confirmDelete) return;
    
    window.showToast("Deleting Player & Purging Data...", "danger");
    try {
        const normTargetName = (name || "").trim().toLowerCase();
        let targetGid = passedGid ? String(passedGid).trim() : (window.nameToIdMap ? window.nameToIdMap[name] : null);
        if (!targetGid && typeof idToNameMap !== 'undefined') {
            for (const [gid, pName] of Object.entries(idToNameMap)) {
                if (pName && pName.toString().trim().toLowerCase() === normTargetName) {
                    targetGid = gid;
                    break;
                }
            }
        }
        
        // 1. Purge from Firebase roster_live node directly by name and GID
        const rosterRemovals = [];
        if (name) {
            rosterRemovals.push(remove(ref(db, `roster_live/${name}`)).catch(() => null));
            rosterRemovals.push(remove(ref(db, `roster_live/${encodeURIComponent(name)}`)).catch(() => null));
            rosterRemovals.push(remove(ref(db, `sheets/Chief's List/${name}`)).catch(() => null));
            rosterRemovals.push(remove(ref(db, `sheets/Chief's List/${encodeURIComponent(name)}`)).catch(() => null));
        }
        if (targetGid) {
            rosterRemovals.push(remove(ref(db, `roster_live/${targetGid}`)).catch(() => null));
            rosterRemovals.push(remove(ref(db, `sheets/Chief's List/${targetGid}`)).catch(() => null));
            rosterRemovals.push(remove(ref(db, `users_alts/${targetGid}`)).catch(() => null));
        }
        await Promise.all(rosterRemovals);
        
        // 2. Search Firebase users node directly and purge matching accounts or linked alts
        const usersSnap = await get(ref(db, 'users')).catch(() => null);
        if (usersSnap && usersSnap.exists()) {
            const users = usersSnap.val() || {};
            for (const [uid, u] of Object.entries(users)) {
                if (!u) continue;
                const uName = (u.name || u.chiefName || u.displayName || "").toString().trim().toLowerCase();
                const uGid = u.gameId ? u.gameId.toString().trim() : "";
                
                // If direct user account match or passedUid match
                if ((passedUid && uid === passedUid) || (!passedUid && ((uName && uName === normTargetName) || (targetGid && uGid === String(targetGid))))) {
                    await remove(ref(db, `users/${uid}`)).catch(() => null);
                    if (!targetGid && uGid) targetGid = uGid;
                }

                // If user owns this as an alt account
                if (targetGid) {
                    if (u.altTokens && u.altTokens[targetGid]) {
                        await remove(ref(db, `users/${uid}/altTokens/${targetGid}`)).catch(() => null);
                    }
                    if (u.linkedAltsData && u.linkedAltsData[targetGid]) {
                        await remove(ref(db, `users/${uid}/linkedAltsData/${targetGid}`)).catch(() => null);
                    }
                    if (Array.isArray(u.linkedGameIds) && u.linkedGameIds.includes(targetGid)) {
                        const updatedGids = u.linkedGameIds.filter(id => String(id).trim() !== String(targetGid));
                        await set(ref(db, `users/${uid}/linkedGameIds`), updatedGids).catch(() => null);
                    }
                }
            }
        }

        // 3. Search Firebase giftcode_bot node directly and purge matching enrollments
        if (targetGid) {
            await remove(ref(db, `giftcode_bot/${targetGid}`)).catch(() => null);
        }
        const gcSnap = await get(ref(db, 'giftcode_bot')).catch(() => null);
        if (gcSnap && gcSnap.exists()) {
            const gcData = gcSnap.val() || {};
            for (const [gId, gObj] of Object.entries(gcData)) {
                if (gObj) {
                    const gcName = (gObj.name || "").toString().trim().toLowerCase();
                    const gcGid = gObj.gameId ? gObj.gameId.toString().trim() : gId;
                    if ((gcName && gcName === normTargetName) || (targetGid && gcGid === String(targetGid))) {
                        await remove(ref(db, `giftcode_bot/${gId}`)).catch(() => null);
                    }
                }
            }
        }

        // 4. Comprehensive Cascade Purge across ALL Event & Data Nodes
        const donKey = normTargetName.replace(/[^a-z0-9]/g, '_');
        const eventRemovals = [];
        
        // Showdown Live
        if (name) {
            eventRemovals.push(remove(ref(db, `showdown_live/${name}`)).catch(() => null));
            eventRemovals.push(remove(ref(db, `showdown_live/${encodeURIComponent(name)}`)).catch(() => null));
            eventRemovals.push(remove(ref(db, `showdown_live/${normTargetName}`)).catch(() => null));
            if (donKey) eventRemovals.push(remove(ref(db, `showdown_live/${donKey}`)).catch(() => null));
        }
        if (targetGid) {
            eventRemovals.push(remove(ref(db, `showdown_live/${targetGid}`)).catch(() => null));
        }

        // Championship (both numeric ID and string name keys)
        if (targetGid) {
            eventRemovals.push(remove(ref(db, `championship/${targetGid}`)).catch(() => null));
        }
        if (donKey) {
            eventRemovals.push(remove(ref(db, `championship/${donKey}`)).catch(() => null));
        }
        if (name) {
            eventRemovals.push(remove(ref(db, `championship/${name}`)).catch(() => null));
            eventRemovals.push(remove(ref(db, `championship/${normTargetName}`)).catch(() => null));
        }

        // Mercenary Prestige
        if (targetGid) {
            eventRemovals.push(remove(ref(db, `mercenary/${targetGid}`)).catch(() => null));
        }
        if (donKey) {
            eventRemovals.push(remove(ref(db, `mercenary/${donKey}`)).catch(() => null));
        }
        if (name) {
            eventRemovals.push(remove(ref(db, `mercenary/${name}`)).catch(() => null));
        }

        // Bear Trap Donations, Wins, and Player Stats
        if (targetGid) {
            eventRemovals.push(remove(ref(db, `beartrap/${targetGid}`)).catch(() => null));
            eventRemovals.push(remove(ref(db, `beartrap_donations/${targetGid}`)).catch(() => null));
            eventRemovals.push(remove(ref(db, `player_event_stats/${targetGid}`)).catch(() => null));
            eventRemovals.push(remove(ref(db, `avatars/${targetGid}`)).catch(() => null));
            eventRemovals.push(remove(ref(db, `staffProfiles/${targetGid}`)).catch(() => null));
        }
        if (donKey) {
            eventRemovals.push(remove(ref(db, `beartrap_donations/${donKey}`)).catch(() => null));
            eventRemovals.push(remove(ref(db, `beartrap_wins/${donKey}`)).catch(() => null));
        }
        if (name) {
            eventRemovals.push(remove(ref(db, `beartrap_wins/${name}`)).catch(() => null));
            eventRemovals.push(remove(ref(db, `beartrap_wins/${normTargetName}`)).catch(() => null));
        }

        await Promise.all(eventRemovals);

        // 5. Instantly clear from local in-memory maps & caches
        if (targetGid) {
            delete idToNameMap[targetGid];
            if (window.idToNameMap) delete window.idToNameMap[targetGid];
        }
        if (name) {
            delete nameToIdMap[name];
            if (window.nameToIdMap) delete window.nameToIdMap[name];
            if (window.rosterCache) delete window.rosterCache[name];
        }
        window.rosterCache = null;

        // Purge global liveData and sheetCache of this player
        if (window.liveData) {
            for (const key of Object.keys(window.liveData)) {
                if (Array.isArray(window.liveData[key])) {
                    window.liveData[key] = window.liveData[key].filter(row => {
                        if (!row || !Array.isArray(row)) return true;
                        const rName = (row[0] || row[1] || '').toString().trim().toLowerCase();
                        const rId = (row[1] || row[2] || '').toString().trim();
                        return rName !== normTargetName && (targetGid ? rId !== String(targetGid) : true);
                    });
                }
            }
        }
        if (window.sheetCache) {
            for (const key of Object.keys(window.sheetCache)) {
                delete window.sheetCache[key];
            }
        }

        // 6. Refresh ID maps from remaining database nodes
        await refreshIdToNameMap();

        // 7. Non-blocking backend delete request to Google Sheets
        try {
            const token = await getAuthToken();
            const url = `${API_BASE_URL}?api=delete_player&name=${encodeURIComponent(name || '')}&gid=${encodeURIComponent(targetGid || '')}&token=${encodeURIComponent(token)}`;
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 4000);
            fetch(url, { signal: controller.signal }).catch(() => null).finally(() => clearTimeout(timeoutId));
        } catch(e) {}
        
        window.showToast(`🗑️ Successfully deleted ${name || 'player'}.`, "success");

        // 8. Refresh UI
        const resDiv = document.getElementById('uniEditorRes');
        if (resDiv) resDiv.style.display = 'none';
        
        if (document.getElementById('playerDirectoryList')) {
            await views.playerEditor();
        } else if (document.querySelector('.admin-tab-content') || document.getElementById('adminHubView')) {
            views.admin('tab-users');
        }
    } catch (e) {
        window.showToast(`Error deleting player: ${e.message}`, "error");
    }
  };

  window.auditAndCleanInactiveEventRecords = async () => {
      const isManager = window.getAdminLevel(currentUser) === 'R5' || window.getAdminLevel(currentUser) === 'R4';
      if (!isManager) {
          if (window.showToast) window.showToast("Only R4/R5 managers can audit and clean event records", "error");
          return;
      }

      if (window.showToast) window.showToast("Auditing event database for inactive/orphaned players...", "info");

      try {
          const [rosterData, sdSnap, champSnap, mercSnap] = await Promise.all([
              window.fetchRoster().catch(() => ({})),
              get(ref(db, 'showdown_live')).catch(() => null),
              get(ref(db, 'championship')).catch(() => null),
              get(ref(db, 'mercenary')).catch(() => null)
          ]);

          const activeNames = new Set();
          const activeGids = new Set();
          if (rosterData) {
              Object.values(rosterData).forEach(p => {
                  if (p.name) activeNames.add(p.name.toString().trim().toLowerCase());
                  if (p.gameId) activeGids.add(p.gameId.toString().trim());
              });
          }

          const sdLive = (sdSnap && sdSnap.exists()) ? (sdSnap.val() || {}) : {};
          const champ = (champSnap && champSnap.exists()) ? (champSnap.val() || {}) : {};
          const merc = (mercSnap && mercSnap.exists()) ? (mercSnap.val() || {}) : {};

          const orphanedSd = [];
          for (const k of Object.keys(sdLive)) {
              if (k.toLowerCase().includes('testing agent') || k === '1' || k === '123456789') {
                  orphanedSd.push(k);
              }
          }

          const orphanedChamp = [];
          for (const [k, v] of Object.entries(champ)) {
              if (k === 'ID' || k === 'Chief Name' || k === '1' || k === '123456789' || (v && v.name && v.name.toLowerCase().includes('testing agent'))) {
                  orphanedChamp.push(k);
              }
          }

          const orphanedMerc = [];
          for (const [k, v] of Object.entries(merc)) {
              if (k === '1' || k === '123456789' || (v && v.name && v.name.toLowerCase().includes('testing agent'))) {
                  orphanedMerc.push(k);
              }
          }

          const totalOrphaned = orphanedSd.length + orphanedChamp.length + orphanedMerc.length;
          if (totalOrphaned === 0) {
              if (window.showToast) window.showToast("✅ All event player records are 100% clean and synced with active roster!", "success");
              return;
          }

          const confirmClean = await window.customConfirm(`🧹 Found ${totalOrphaned} orphaned/test event records:\n\n• Showdown: ${orphanedSd.length}\n• Championship: ${orphanedChamp.length}\n• Mercenary: ${orphanedMerc.length}\n\nPurge these records now?`);
          if (!confirmClean) return;

          for (const k of orphanedSd) await remove(ref(db, `showdown_live/${k}`)).catch(() => null);
          for (const k of orphanedChamp) await remove(ref(db, `championship/${k}`)).catch(() => null);
          for (const k of orphanedMerc) await remove(ref(db, `mercenary/${k}`)).catch(() => null);

          if (window.showToast) window.showToast(`✅ Successfully purged ${totalOrphaned} orphaned event records!`, "success");
          if (window.activeViewFunc) window.activeViewFunc();
      } catch(err) {
          console.error("Event audit error:", err);
          if (window.showToast) window.showToast("Error during event audit: " + err.message, "error");
      }
  };

