window.getLivePlayerEventRow = async (chiefName, pRow, headers) => {
    if (!chiefName) return pRow;
    const row = pRow ? [...pRow] : [chiefName, 0, false, false, false, false];
    const playerGameId = window.nameToIdMap ? window.nameToIdMap[chiefName] : null;
    const gIdStr = (playerGameId && playerGameId.toString().trim()) ? playerGameId.toString().trim() : (chiefName ? chiefName.toLowerCase().replace(/[^a-z0-9]/g, '_') : '');

    if (!gIdStr) return row;

    try {
        const [actSnap, statsSnap] = await Promise.all([
            get(ref(db, `activity_live/${gIdStr}`)).catch(() => null),
            get(ref(db, `player_event_stats/${gIdStr}`)).catch(() => null)
        ]);

        const actData = (actSnap && actSnap.exists()) ? (actSnap.val() || {}) : {};
        const statsData = (statsSnap && statsSnap.exists()) ? (statsSnap.val() || {}) : null;

        const isT = (v) => v === true || v === 'true' || v === 'yes' || v === 'YES' || v === 1;

        const liveChamp = isT(actData.championship);
        const liveMerc = isT(actData.mercenary);
        const livePt = isT(actData.polarTerrors);
        const liveVoter = isT(actData.voter);

        const safeHeaders = headers || ["Chief Name", "ShowDown missed days", "Alliance Championship ", "Mercenary Prestige", "Polar Terrors", "Voter"];

        for (let col = 1; col < safeHeaders.length; col++) {
            const h = (safeHeaders[col] || '').toLowerCase();
            if (h.includes('championship')) {
                row[col] = liveChamp;
            } else if (h.includes('mercenary')) {
                row[col] = liveMerc;
            } else if (h.includes('polar')) {
                row[col] = livePt;
            } else if (h.includes('voter')) {
                row[col] = liveVoter;
            }
        }

        row._eventStats = statsData;
    } catch(e) { console.warn("Error fetching live player event status:", e); }

    return row;
};

  window.doPlayerLookup = async (playerName) => {
    let name = playerName ? playerName : document.getElementById('rosterPlayerSelect').value;
    if (!name) return;
    
    // Check if the input is actually a game ID
    if (!isNaN(name) && name.length >= 7) {
       await refreshIdToNameMap();
       let foundName = idToNameMap[name];
       if (foundName) name = foundName;
       else if(window.showToast) {
          window.showToast("Could not resolve ID to player name", "error");
          return;
       }
    }
    
    const resDiv = document.getElementById('rosterLookupResult');
    if (!resDiv) {
      if (document.getElementById('playerLookupCustomDropdown')) {
        document.getElementById('playerLookupCustomDropdown').style.display = 'none';
      }
      return;
    }
    
    resDiv.style.display = 'block';
    if (!window.liveData || !window.liveData["activity "]) {
      resDiv.innerHTML = '<div style="text-align:center; padding:20px;"><span style="color:var(--text-muted)">Querying master database...</span></div>';
    }
    
    try {

      

      const [rawActivityData, rosterRawData, lbRawData, sdHistoryRawData, sdLiveSnap] = await Promise.all([
        window.fetchActivityData().catch(() => []),
        window.fetchRoster().catch(() => ({})),
        window.fetchLeaderboardsData().catch(() => null),
        fetchSheet("Showdown History").catch(() => []),
        get(ref(db, 'showdown_live')).catch(() => null)
      ]);
      
      const sdLiveData = (sdLiveSnap && sdLiveSnap.exists()) ? (sdLiveSnap.val() || {}) : {};
  
      let currentDay = 0;
      Object.values(sdLiveData).forEach(p => {
         if (!p || typeof p !== 'object') return;
         if ((p.d6||0) > 0 && currentDay < 6) currentDay = 6;
         else if ((p.d5||0) > 0 && currentDay < 5) currentDay = 5;
         else if ((p.d4||0) > 0 && currentDay < 4) currentDay = 4;
         else if ((p.d3||0) > 0 && currentDay < 3) currentDay = 3;
         else if ((p.d2||0) > 0 && currentDay < 2) currentDay = 2;
         else if ((p.d1||0) > 0 && currentDay < 1) currentDay = 1;
      });

      const lookupDefaultHeaders = ["Chief Name", "ShowDown missed days", "Alliance Championship ", "Mercenary Prestige", "Polar Terrors", "Voter"];
      let data = [];

      if (Array.isArray(rawActivityData) && rawActivityData.length > 0) {
        data = rawActivityData;
      } else if (rawActivityData && typeof rawActivityData === 'object') {
        data = [lookupDefaultHeaders];
        Object.values(rawActivityData).forEach(rec => {
          if (rec && typeof rec === 'object' && rec.name) {
            data.push([rec.name, 0, rec.championship || false, rec.mercenary || false, rec.polarTerrors || false, false]);
          }
        });
      }

      if (!Array.isArray(data) || data.length < 2) {
        data = [lookupDefaultHeaders];
        const knownNames = new Set();
        if (rosterRawData && typeof rosterRawData === 'object') {
          Object.values(rosterRawData).forEach(p => { if (p && p.name) knownNames.add(p.name.toString().trim()); });
        }
        if (typeof idToNameMap === 'object') {
          Object.values(idToNameMap).forEach(n => { if (n) knownNames.add(n.toString().trim()); });
        }
        if (sdLiveData && typeof sdLiveData === 'object') {
          Object.keys(sdLiveData).forEach(n => { if (n) knownNames.add(n.toString().trim()); });
        }
        Array.from(knownNames).sort((a, b) => a.localeCompare(b)).forEach(n => {
          data.push([n, 0, false, false, false, false]);
        });
      }

      if (data && data.length > 1) {
          for (let r = 1; r < data.length; r++) {
             let pName = data[r][0];
             if (!pName) continue;
             let safeName = pName.toString().trim();
             let missedCount = 0;
             if (currentDay > 0) {
                let p = sdLiveData[safeName] || {};
                for (let i = 1; i <= currentDay; i++) {
                   if (!(p['d'+i] > 0)) missedCount++;
                }
             }
             data[r][1] = missedCount;
          }
      }
          
      let usersSnap = null;
      try { usersSnap = await get(ref(db, 'users')); } catch(e) { console.warn("Could not fetch users:", e); }
      
      // Parse Maps
      const rosterMap = rosterRawData || {};
      
  
  
      let btDonationsAllTime = null, btDonationsCurrent = null, bear1 = null, bear2 = null, bearBoth = null, bearAllTime = null;
      let otherLbs = [];
      
      if (lbRawData) {
        for (let r = 0; r < lbRawData.length; r++) {
          for (let c = 0; c < lbRawData[r].length; c++) {
            let cell = lbRawData[r][c];
            if (typeof cell === 'string' && cell.trim() !== '' && (
              cell.toLowerCase().includes('leaderboard') || 
              cell.toLowerCase().includes('ranking') || 
              cell.toLowerCase().includes('bear') || 
              cell.toLowerCase().includes('showdown') ||
              cell.toLowerCase().includes('championship') ||
              cell.toLowerCase().includes('mercenary') ||
              cell.toLowerCase().includes('polar')
            )) {
              let title = cell.replace(/leaderboard/i, '').replace(/ranking/i, '').trim();
              if (!title) title = "Leaderboard";
              
              let scoreCol = c + 1;
              for (let i = c + 1; i <= c + 10; i++) {
                if (!lbRawData[r+1] || !lbRawData[r+1][i]) break;
                scoreCol = i;
              }
              
              let hr = r + 2;
              while (hr < lbRawData.length && lbRawData[hr][c] && lbRawData[hr][c].toString().trim() !== "") {
                let pName = lbRawData[hr][c+1];
                let score = lbRawData[hr][scoreCol];
                if (pName && pName.toString().trim().toLowerCase() === targetName.toLowerCase() && score !== undefined && score !== "") {
                  let playerPosRank = hr - (r + 1);
                  let rawRank = (lbRawData[hr][c] !== undefined && lbRawData[hr][c] !== null && lbRawData[hr][c] !== "" && !isNaN(lbRawData[hr][c]) && Number(lbRawData[hr][c]) !== hr) ? Number(lbRawData[hr][c]) : playerPosRank;
                  let rank = rawRank;
                  if (typeof rawRank === 'number') {
                     if (rawRank === 1) rank = '🥇 1st';
                     else if (rawRank === 2) rank = '🥈 2nd';
                     else if (rawRank === 3) rank = '🥉 3rd';
                     else rank = `#${rawRank}`;
                  }
                  
                  let isAllTime = title.toLowerCase().includes("all-time") || title.toLowerCase().includes("all time");
                  let isBear = title.toLowerCase().includes("bear") || title.toLowerCase().includes("bt");
                  
                  let formattedScore = score;
                  if (typeof score === 'number') {
                    formattedScore = score.toLocaleString();
                  }
                  
                  let emoji = "🏆";
                  if (isBear) emoji = "🐻";
                  else if (title.toLowerCase().includes("showdown")) emoji = "⚔️";
                  else if (title.toLowerCase().includes("championship")) emoji = "👑";
                  else if (title.toLowerCase().includes("mercenary")) emoji = "🗡️";

                  if (isBear && isAllTime && title.toLowerCase().includes("donation")) btDonationsAllTime = { score: formattedScore, rank };
                  else if (isBear && title.toLowerCase().includes("donation")) btDonationsCurrent = { score: formattedScore, rank };
                  else if (isBear && isAllTime) bearAllTime = { score: formattedScore, rank };
                  else if (isBear && title.toLowerCase().includes("1")) bear1 = { score: formattedScore, rank };
                  else if (isBear && title.toLowerCase().includes("2")) bear2 = { score: formattedScore, rank };
                  else if (isBear && title.toLowerCase().includes("both")) bearBoth = { score: formattedScore, rank };
                  else otherLbs.push({ title, score: formattedScore, rank, emoji });
                }
                hr++;
              }
            }
          }
        }
      }
      
      const allTimeShowdownMap = {};
      const processShowdownTable = (tableData) => {
        if (!tableData) return;
        for (let r = 0; r < tableData.length; r++) {
          let row = tableData[r];
          if (row.some(c => typeof c === 'string' && c.toLowerCase().trim() === 'ranking')) {
            let nameCol = row.findIndex(c => typeof c === 'string' && (c.toLowerCase().includes('name') || c.toLowerCase().includes('member') || c.toLowerCase().includes('player')));
            let totalCol = row.findIndex(c => typeof c === 'string' && (c.toLowerCase().includes('total')));
            if (nameCol !== -1 && totalCol !== -1) {
              let dr = r + 1;
              while (dr < tableData.length && tableData[dr][nameCol] && (tableData[dr][nameCol].toString().toLowerCase().includes('horns') || tableData[dr][nameCol].toString().toLowerCase().includes('winners'))) dr++;
              while (dr < tableData.length && tableData[dr][nameCol] !== undefined && tableData[dr][nameCol] !== "") {
                let pName = tableData[dr][nameCol];
                let pScore = tableData[dr][totalCol];
                if (pName && (typeof pScore === 'number' || (typeof pScore === 'string' && !isNaN(pScore)))) {
                  let rawName = pName.toString().trim();
                  let san = rawName.toLowerCase().replace(/[^a-z0-9]/g, '');
                  let safeKey = san.length > 0 ? san : rawName.toLowerCase();
                  if (!allTimeShowdownMap[safeKey]) allTimeShowdownMap[safeKey] = { name: rawName, score: 0 };
                  allTimeShowdownMap[safeKey].score += Number(pScore);
                }
                dr++;
              }
            }
          }
        }
      };
      processShowdownTable(sdHistoryRawData);
      
      for (const [pName, scores] of Object.entries(sdLiveData)) {
          if (!scores || typeof scores !== 'object') continue;
          let rawName = (scores.name || pName).toString().trim();
          let san = rawName.toLowerCase().replace(/[^a-z0-9]/g, '');
          let safeKey = san.length > 0 ? san : rawName.toLowerCase();
          let pScore = (scores.d1||0) + (scores.d2||0) + (scores.d3||0) + (scores.d4||0) + (scores.d5||0) + (scores.d6||0);
          if (!allTimeShowdownMap[safeKey]) allTimeShowdownMap[safeKey] = { name: rawName, score: 0 };
          allTimeShowdownMap[safeKey].score += pScore;
      }

    
    let dynamicSD = null;
    const sortedShowdownPlayers = Object.values(allTimeShowdownMap).sort((a, b) => b.score - a.score);
    sortedShowdownPlayers.forEach((p, index) => {
      if (p.name.toLowerCase() === targetName.toLowerCase()) dynamicSD = { score: p.score, rank: index + 1 };
    });
    
    const lookupCardDefaultHeaders = ["Chief Name", "ShowDown missed days", "Alliance Championship ", "Mercenary Prestige", "Polar Terrors", "Voter"];
    const headers = (data && data[0] && Array.isArray(data[0])) ? data[0] : lookupCardDefaultHeaders;
    let showdownActive = false;
    let colIsUpcoming = {};
    let dataRows = Array.isArray(data) ? data : (data && typeof data === 'object' ? Object.values(data).filter(v => Array.isArray(v)) : []);
    for (let c = 1; c < headers.length; c++) {
       let hasAnyTrue = false;
       for (let r = 0; r < dataRows.length; r++) {
          let v = dataRows[r][c];
          if (c === 1 && dataRows[r]) {
             let missed = dataRows[r][1];
             if (missed !== undefined && missed !== null && missed.toString().trim() !== "" && missed !== 0 && missed !== "0") showdownActive = true;
          }
          if (v === true || (typeof v === 'string' && (v.toLowerCase().trim() === 'true' || v.toLowerCase().trim() === 'yes'))) hasAnyTrue = true;
       }
       colIsUpcoming[c] = !hasAnyTrue;
    }
    
    if (!targetName && name) targetName = name.trim();
    let pRow = null;
    if (dataRows && dataRows.length > 0) {
      for (let i = 0; i < dataRows.length; i++) {
         if (dataRows[i][0] && dataRows[i][0].toString().trim().toLowerCase() === targetName.toLowerCase()) { 
             pRow = dataRows[i]; 
             targetName = dataRows[i][0].toString().trim();
             break; 
         }
      }
    }
    
    if (!pRow) {
      for (const [gid, chiefName] of Object.entries(idToNameMap)) {
         if (chiefName && chiefName.toLowerCase().trim() === targetName.toLowerCase()) {
            targetName = chiefName;
            pRow = [targetName, 0, false, false, false, false, false];
            break;
         }
      }
    }
    
    if (!pRow) throw new Error(`Chief "${name}" not found in roster or activity database.`);

    pRow = await window.getLivePlayerEventRow(targetName, pRow, headers);
    
    // Generate HTML
    let altAccounts = [];
    const viewedGameId = nameToIdMap[name];
    const ROOT_ADMIN_GAME_ID = 318843189;
    const viewerIsR5 = window.getAdminLevel(currentUser) === 'R5';
    // Alt accounts are strictly private - only the logged-in owner can view their own alts
    const isOwnerOfProfile = currentUser && (
        (viewedGameId && currentUser.gameId && Number(currentUser.gameId) === Number(viewedGameId)) ||
        (currentUser.name && targetName && currentUser.name.toString().trim().toLowerCase() === targetName.toString().trim().toLowerCase()) ||
        (currentUser.chiefName && targetName && currentUser.chiefName.toString().trim().toLowerCase() === targetName.toString().trim().toLowerCase())
    );

    if (isOwnerOfProfile && usersSnap && usersSnap.exists()) {
        const users = usersSnap.val();
        if (viewedGameId) {
            for (const u of Object.values(users)) {
                if (Number(u.gameId) === Number(viewedGameId)) {
                    if (u.linkedGameIds && Array.isArray(u.linkedGameIds)) {
                        altAccounts = [...new Set([...altAccounts, ...u.linkedGameIds])];
                    }
                }
            }
        }
    }
    
    let resolvedRosterInfo = {};
    if (rosterMap && typeof rosterMap === 'object') {
       const directKey = Object.keys(rosterMap).find(k => k.toLowerCase().trim() === targetName.toLowerCase().trim());
       if (directKey) {
          resolvedRosterInfo = { ...rosterMap[directKey] };
       } else {
          const valMatch = Object.values(rosterMap).find(v => 
             v && typeof v === 'object' && (
                (v.name && v.name.toString().toLowerCase().trim() === targetName.toLowerCase().trim()) ||
                (v.chiefName && v.chiefName.toString().toLowerCase().trim() === targetName.toLowerCase().trim()) ||
                (viewedGameId && v.gameId && v.gameId.toString().trim() === viewedGameId.toString().trim())
             )
          );
          if (valMatch) resolvedRosterInfo = { ...valMatch };
       }
    }
    if (!resolvedRosterInfo.furnaceLevel && viewedGameId && rosterMap && rosterMap[viewedGameId]) {
       resolvedRosterInfo = { ...resolvedRosterInfo, ...rosterMap[viewedGameId] };
    }
    if (usersSnap && usersSnap.exists()) {
       const users = usersSnap.val();
       for (const u of Object.values(users)) {
          const uGid = u.gameId ? u.gameId.toString().trim() : '';
          const uName = (u.name || u.chiefName || '').toString().trim();
          if ((viewedGameId && uGid === viewedGameId.toString().trim()) || (targetName && uName.toLowerCase() === targetName.toLowerCase())) {
             if (u.stove_lv || u.furnaceLevel) {
                resolvedRosterInfo = {
                   ...resolvedRosterInfo,
                   furnaceLevel: u.stove_lv || u.furnaceLevel,
                   stove_lv: u.stove_lv || u.furnaceLevel
                };
             }
             break;
          }
       }
    }
    if (!resolvedRosterInfo.gameId && viewedGameId) resolvedRosterInfo.gameId = viewedGameId;
    
    const isUserAdmin = window.isAdminUser(currentUser);
    let html = window.generatePlayerProfileHtml(targetName, pRow, headers, colIsUpcoming, resolvedRosterInfo, null, dynamicSD, showdownActive, bearBoth, bear1, bear2, bearAllTime, btDonationsAllTime, btDonationsCurrent, otherLbs, isUserAdmin, altAccounts, isUserAdmin);
    
    resDiv.innerHTML = html;
    
  } catch (err) {
    resDiv.innerHTML = `<span style="color:var(--danger)">Error: ${err.message}</span>`;
  }
};

window.searchPlayerFull = async (name) => {
  if (!currentUser) return window.renderMembersOnlyGuard("Player Profile Cards");
  let targetName = name ? name.replace(/^✅\s*/, '').trim() : '';
  window.activeViewFunc = () => window.searchPlayerFull(name);
  
  let resDiv = document.getElementById('uniEditorRes');
  if (!resDiv) {
    if (views.playerEditor) await views.playerEditor();
    resDiv = document.getElementById('uniEditorRes');
    const searchInput = document.getElementById('uniSearchInput');
    if (searchInput) searchInput.value = targetName;
  }

  if (!resDiv) return;
  if (!targetName) {
    resDiv.style.display = 'none';
    return;
  }
  
  resDiv.style.display = 'block';
  if (!window.liveData || !window.liveData["activity "]) {
    resDiv.innerHTML = '<div style="text-align:center; padding:20px;"><span style="color:var(--text-muted)">Querying master database...</span></div>';
  }
  
  try {
    let sdLiveSnapshotPromise = window.fetchMergedShowdown();
    const [data, rosterRawData, lbRawData, sdHistSnap, sdMergedDataRes, fbWinsSnap, fbDonSnap] = await Promise.all([
            window.fetchActivityData().catch(() => []),
            window.fetchRoster().catch(() => ({})),
            window.fetchLeaderboardsData().catch(() => []),
            get(ref(db, 'showdown_meta/history')).catch(() => null),
            sdLiveSnapshotPromise.catch(() => ({ mergedData: [], sdLiveData: {} })),
            get(ref(db, 'beartrap_wins')).catch(() => null),
            get(ref(db, 'beartrap_donations')).catch(() => null)
          ]);
    const sdHistoryRawData = (sdHistSnap && sdHistSnap.exists()) ? sdHistSnap.val() : [];
    const sdCurrentRawData = (sdMergedDataRes && sdMergedDataRes.mergedData) ? sdMergedDataRes.mergedData : [];
    const sdLiveData = (sdMergedDataRes && sdMergedDataRes.sdLiveData) ? sdMergedDataRes.sdLiveData : {};
    const fbWins = (fbWinsSnap && fbWinsSnap.exists()) ? fbWinsSnap.val() : {};
    const fbDonations = (fbDonSnap && fbDonSnap.exists()) ? fbDonSnap.val() : {};

    let currentDay = 0;
    Object.values(sdLiveData).forEach(p => {
       if ((p.d6||0) > 0 && currentDay < 6) currentDay = 6;
       else if ((p.d5||0) > 0 && currentDay < 5) currentDay = 5;
       else if ((p.d4||0) > 0 && currentDay < 4) currentDay = 4;
       else if ((p.d3||0) > 0 && currentDay < 3) currentDay = 3;
       else if ((p.d2||0) > 0 && currentDay < 2) currentDay = 2;
       else if ((p.d1||0) > 0 && currentDay < 1) currentDay = 1;
    });
    if (data && data.length > 1) {
        for (let r = 1; r < data.length; r++) {
           let pName = data[r][0];
           if (!pName) continue;
           let safeName = pName.toString().trim();
           let missedCount = 0;
           if (currentDay > 0) {
              let p = sdLiveData[safeName] || {};
              for (let i = 1; i <= currentDay; i++) {
                 if (!(p['d'+i] > 0)) missedCount++;
              }
           }
           data[r][1] = missedCount;
        }
    }
        
        let usersSnap = null;
        try { usersSnap = await get(ref(db, 'users')); } catch(e) { console.warn("Could not fetch users:", e); }
    
    // Parse Maps
    const rosterMap = rosterRawData || {};
    


    const parsedLbRes = window.computeLiveFirebasePlayerStats(targetName, fbWins, fbDonations, lbRawData);
    let { btDonationsAllTime, btDonationsCurrent, bear1, bear2, bearBoth, bearAllTime, otherLbs, lbMap } = parsedLbRes;
    
    const showdownHistObj = (sdHistSnap && sdHistSnap.exists()) ? sdHistSnap.val() : {};
    const historyObjMerged = (typeof window.getMergedShowdownHistoryObj === 'function') 
      ? window.getMergedShowdownHistoryObj(showdownHistObj) 
      : showdownHistObj;
    let allTimePlayersModal = (typeof window.calculateAllTimeShowdown === 'function') 
      ? window.calculateAllTimeShowdown(historyObjMerged) 
      : [];

    const modalSdMap = {};
    allTimePlayersModal.forEach(p => {
      if (p && p.name) {
        const san = p.name.toLowerCase().replace(/[^a-z0-9]/g, '');
        const sKey = san.length > 0 ? san : p.name.toLowerCase().trim();
        if (!modalSdMap[sKey]) {
          modalSdMap[sKey] = { name: p.name, horns: p.horns || 0, wins: p.wins || 0, score: p.total || 0 };
        } else {
          modalSdMap[sKey].score += (p.total || 0);
          modalSdMap[sKey].horns += (p.horns || 0);
          modalSdMap[sKey].wins += (p.wins || 0);
        }
      }
    });

    if (sdLiveData && typeof sdLiveData === 'object') {
      for (const [pKey, scores] of Object.entries(sdLiveData)) {
        if (!scores || typeof scores !== 'object') continue;
        let realName = scores.name || pKey;
        let san = realName.toLowerCase().replace(/[^a-z0-9]/g, '');
        let sKey = san.length > 0 ? san : realName.toLowerCase().trim();
        let pTotal = Number(scores.total !== undefined ? scores.total : ((scores.d1||0) + (scores.d2||0) + (scores.d3||0) + (scores.d4||0) + (scores.d5||0) + (scores.d6||0)));
        if (!modalSdMap[sKey]) {
          modalSdMap[sKey] = { name: realName, horns: 0, wins: 0, score: 0 };
        }
        modalSdMap[sKey].score += pTotal;
      }
    }

    let dynamicSD = null;
    const sanTarget = targetName.toLowerCase().replace(/[^a-z0-9]/g, '');
    const targetSanitizedKey = sanTarget.length > 0 ? sanTarget : targetName.toLowerCase().trim();
    const sortedShowdownPlayers = Object.values(modalSdMap).sort((a, b) => (b.horns !== a.horns) ? (b.horns - a.horns) : (b.score - a.score));
    sortedShowdownPlayers.forEach((p, index) => {
      const sanP = p.name.toLowerCase().replace(/[^a-z0-9]/g, '');
      const keyP = sanP.length > 0 ? sanP : p.name.toLowerCase().trim();
      if (keyP === targetSanitizedKey) {
        dynamicSD = { score: p.score, rank: index + 1 };
      }
    });
    
    const defaultHeaders = ["Chief Name", "ShowDown missed days", "Alliance Championship ", "Mercenary Prestige", "Polar Terrors", "Voter"];
    const headers = (data && data[0] && Array.isArray(data[0])) ? data[0] : defaultHeaders;
    let showdownActive = false;
    let colIsUpcoming = {};
    let dataRows = Array.isArray(data) ? data : (data && typeof data === 'object' ? Object.values(data).filter(v => Array.isArray(v)) : []);
    for (let c = 1; c < headers.length; c++) {
       let hasAnyTrue = false;
       for (let r = 0; r < dataRows.length; r++) {
          let v = dataRows[r][c];
          if (c === 1 && dataRows[r]) {
             let missed = dataRows[r][1];
             if (missed !== undefined && missed !== null && missed.toString().trim() !== "" && missed !== 0 && missed !== "0") showdownActive = true;
          }
          if (v === true || (typeof v === 'string' && (v.toLowerCase().trim() === 'true' || v.toLowerCase().trim() === 'yes'))) hasAnyTrue = true;
       }
       colIsUpcoming[c] = !hasAnyTrue;
    }
    
    const normalizeSearchKey = (str) => {
      if (!str) return '';
      return String(str)
        .replace(/[\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
    };
    const normAlphaKey = (str) => {
      if (!str) return '';
      return String(str).toLowerCase().replace(/[^a-z0-9]/g, '');
    };

    if (!targetName && name) targetName = String(name).trim();
    const cleanTarget = normalizeSearchKey(targetName);
    const alphaTarget = normAlphaKey(targetName);

    let pRow = null;

    // 1. Check dataRows (Activities sheet / Roster data)
    if (dataRows && dataRows.length > 0) {
      for (let i = 0; i < dataRows.length; i++) {
         const rowName = dataRows[i][0] ? String(dataRows[i][0]) : '';
         if (!rowName) continue;
         if (normalizeSearchKey(rowName) === cleanTarget || (alphaTarget && normAlphaKey(rowName) === alphaTarget)) { 
             pRow = dataRows[i]; 
             targetName = rowName.replace(/[\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]/g, ' ').trim();
             break; 
         }
      }
    }
    
    // 2. Check idToNameMap / nameToIdMap
    if (!pRow && idToNameMap) {
      // Check if target is a Game ID directly
      if (idToNameMap[targetName] || idToNameMap[cleanTarget]) {
        targetName = idToNameMap[targetName] || idToNameMap[cleanTarget];
        pRow = [targetName, 0, false, false, false, false, false];
      } else {
        for (const [gid, chiefName] of Object.entries(idToNameMap)) {
           if (chiefName && (normalizeSearchKey(chiefName) === cleanTarget || (alphaTarget && normAlphaKey(chiefName) === alphaTarget))) {
              targetName = chiefName.replace(/[\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]/g, ' ').trim();
              pRow = [targetName, 0, false, false, false, false, false];
              break;
           }
        }
      }
    }
    
    // 3. Check rosterRawData (roster_live)
    if (!pRow && rosterRawData && typeof rosterRawData === 'object') {
      for (const [pName, pObj] of Object.entries(rosterRawData)) {
         const cleanPName = pName ? pName.replace(/[\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]/g, ' ').trim() : '';
         const objGameId = pObj && pObj.gameId ? String(pObj.gameId).trim() : '';
         if (normalizeSearchKey(cleanPName) === cleanTarget || (alphaTarget && normAlphaKey(cleanPName) === alphaTarget) || objGameId === targetName) {
             targetName = cleanPName;
             pRow = [targetName, 0, false, false, false, false, false];
             break;
         }
      }
    }

    // 4. Check Firebase Registered Users (users collection)
    if (!pRow && usersSnap && usersSnap.exists()) {
      const uData = usersSnap.val() || {};
      for (const u of Object.values(uData)) {
        if (!u) continue;
        const uName = (u.name || u.chiefName || '').toString().replace(/[\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]/g, ' ').trim();
        const uGid = u.gameId ? String(u.gameId).trim() : '';
        if ((uName && (normalizeSearchKey(uName) === cleanTarget || (alphaTarget && normAlphaKey(uName) === alphaTarget))) || (uGid && uGid === targetName)) {
          targetName = uName || `Chief ${uGid}`;
          pRow = [targetName, 0, false, false, false, false, false];
          break;
        }
      }
    }
    
    if (!pRow) {
      resDiv.innerHTML = `
        <div style="padding:24px; text-align:center; background:rgba(239,68,68,0.1); border:1px solid rgba(239,68,68,0.3); border-radius:12px; color:var(--danger); margin-top:15px; animation:fadeIn 0.3s ease;">
            <h3 style="margin:0 0 8px 0; font-size:18px; display:flex; align-items:center; justify-content:center; gap:8px;">⚠️ Player Not Found</h3>
            <p style="margin:0; font-size:14px; color:var(--text-muted);">Player <strong>"${window.escapeHTML(targetName)}"</strong> does not exist in any database or has been deleted.</p>
        </div>`;
      return;
    }

    pRow = await window.getLivePlayerEventRow(targetName, pRow, headers);
    
    // Generate HTML
    let altAccounts = [];
    const viewedGameId = nameToIdMap[targetName] || nameToIdMap[name];
    const ROOT_ADMIN_GAME_ID = 318843189;
    const viewerIsR5 = window.getAdminLevel(currentUser) === 'R5';
    // Alt accounts are strictly private - only the logged-in owner can view their own alts
    const isOwnerOfProfile = currentUser && (
        (viewedGameId && currentUser.gameId && Number(currentUser.gameId) === Number(viewedGameId)) ||
        (currentUser.name && targetName && currentUser.name.toString().trim().toLowerCase() === targetName.toString().trim().toLowerCase()) ||
        (currentUser.chiefName && targetName && currentUser.chiefName.toString().trim().toLowerCase() === targetName.toString().trim().toLowerCase())
    );

    if (isOwnerOfProfile && usersSnap && usersSnap.exists()) {
        const users = usersSnap.val();
        if (viewedGameId) {
            for (const u of Object.values(users)) {
                if (Number(u.gameId) === Number(viewedGameId)) {
                    if (u.linkedGameIds && Array.isArray(u.linkedGameIds)) {
                        altAccounts = [...new Set([...altAccounts, ...u.linkedGameIds])];
                    }
                }
            }
        }
    }
    
    const isUserAdmin = window.isAdminUser(currentUser);
    let html = window.generatePlayerProfileHtml(targetName, pRow, headers, colIsUpcoming, rosterMap[targetName], null, dynamicSD, showdownActive, bearBoth, bear1, bear2, bearAllTime, btDonationsAllTime, btDonationsCurrent, otherLbs, isUserAdmin, altAccounts, isUserAdmin);
    
    resDiv.innerHTML = html;
    
  } catch (err) {
    resDiv.innerHTML = `<span style="color:var(--danger)">Error: ${err.message}</span>`;
  }
};

window.savePlayerFull = async (name) => {
  const ptStatus = document.getElementById('uniPtSelect').value;
  const acStatus = document.getElementById('uniAcSelect').value;
  const btAdd = document.getElementById('uniBtAdd').value;
  const resDiv = document.getElementById('uniEditorRes');
  
  const adminName = currentUser ? (idToNameMap[currentUser.gameId] || "Admin") : "Admin";
  
  resDiv.innerHTML = '<span style="color:var(--text-muted)">Saving changes to master sheets...</span>';
  
  try {
    const token = await getAuthToken();
    const res = await fetch(`${API_BASE_URL}?api=updateFull&name=${encodeURIComponent(name)}&ptStatus=${encodeURIComponent(ptStatus)}&acStatus=${encodeURIComponent(acStatus)}&btAdd=${encodeURIComponent(btAdd)}&admin=${encodeURIComponent(adminName)}&token=${encodeURIComponent(token)}`).then(r => r.json());
    if (res.success) {
      window.showToast("Player updated successfully!", "success");
      let successMsg = `<div style="color:var(--success); font-weight:bold; margin-bottom:5px;">✅ ${res.message}</div>`;
      if (res.btRes && res.btRes.success) {
        successMsg += `<div style="font-size:13px; color:var(--text-muted);">New Bear Total: ${res.btRes.newTotal}</div>`;
      }
      resDiv.innerHTML = successMsg;
    } else {
      resDiv.innerHTML = `<span style="color:var(--danger)">Error: ${res.message}</span>`;
    }
  } catch (err) {
    resDiv.innerHTML = `<span style="color:var(--danger)">Network Error: ${err.message}</span>`;
  }
};

onValue(ref(db, 'config/maintenanceMode'), (snapshot) => {
  maintenanceMode = snapshot.val() || false;
  checkMaintenanceAccess();
});

// Welcome Popup Banner (Disabled per clean login design)
window.showWelcomePop = () => {};

// Dedicated Chief Navbar Indicator Updater
window.updateNavbarUserIndicator = (user = currentUser) => {
    const navIndicator = document.getElementById('navbar-user-indicator');
    if (!navIndicator) return;
    
    if (!user) {
        navIndicator.style.display = 'none';
        navIndicator.innerHTML = '';
        return;
    }
    
    const isSpoofing = Boolean(window._spoofedUser);
    const gId = user.gameId ? String(user.gameId).trim() : '';
    let name = '';
    
    if (gId && window.idToNameMap && window.idToNameMap[gId] && !/^\d+$/.test(window.idToNameMap[gId])) {
        name = window.idToNameMap[gId];
    } else if (gId && typeof idToNameMap !== 'undefined' && idToNameMap[gId] && !/^\d+$/.test(idToNameMap[gId])) {
        name = idToNameMap[gId];
    } else if (user.name && String(user.name).trim() && !/^\d+$/.test(String(user.name).trim())) {
        name = String(user.name).trim();
    } else if (user.chiefName && String(user.chiefName).trim() && !/^\d+$/.test(String(user.chiefName).trim())) {
        name = String(user.chiefName).trim();
    } else if (user.displayName && String(user.displayName).trim()) {
        name = String(user.displayName).trim();
    } else if (user.email && user.email.includes('@')) {
        name = user.email.split('@')[0];
    } else {
        name = 'Chief';
    }
    
    if (isSpoofing) {
        navIndicator.innerHTML = `🎭 Spoofing: ${window.escapeHTML(name)}`;
        navIndicator.style.display = 'flex';
        navIndicator.style.color = '#ef4444';
        navIndicator.style.borderColor = 'rgba(239, 68, 68, 0.4)';
        navIndicator.style.background = 'rgba(239, 68, 68, 0.15)';
    } else {
        const isStaff = (typeof window.isAdminUser === 'function') && window.isAdminUser(user);
        const icon = isStaff ? '👑' : '👤';
        navIndicator.innerHTML = `${icon} ${window.escapeHTML(name)}`;
        navIndicator.style.display = 'flex';
        navIndicator.style.color = '#60a5fa';
        navIndicator.style.borderColor = 'rgba(59, 130, 246, 0.4)';
        navIndicator.style.background = 'rgba(59, 130, 246, 0.18)';
    }
};

