// Listen to Auth State
let realUser = null; // Store the actual logged in user so we can revert from spoofing

listenToAuth((user) => {
  if (!window._spoofedUser) {
      currentUser = user;
  }
  realUser = user;
  
  const adminAlertsNavBtn = document.getElementById('adminAlertsNavBtn');

  if (currentUser) {
    if (currentUser.uid && typeof window.setupUserRealtimeSync === 'function') {
      window.setupUserRealtimeSync(currentUser.uid);
    }
    let name = (currentUser.gameId && window.idToNameMap && window.idToNameMap[currentUser.gameId]) 
      ? window.idToNameMap[currentUser.gameId] 
      : (currentUser.name || currentUser.chiefName || currentUser.displayName || 'Chief');
      
    if(authSidebarBtn) authSidebarBtn.innerHTML = window._spoofedUser ? `🎭 Spoofing: ${name}` : `👤 Account Hub`;
    if (adminAlertsNavBtn) adminAlertsNavBtn.style.display = 'flex';
    if (window.updateNewMemberBadge) window.updateNewMemberBadge();
    
    if(signOutSidebarBtn) signOutSidebarBtn.style.display = 'inline-flex';
    
    window.updateNavbarUserIndicator(currentUser);
    if (window.syncAllClaimedUsersToGiftbot) {
      window.syncAllClaimedUsersToGiftbot().catch(() => null);
    }
    
    // Automatically remove onboarding banner and refresh views on sign-in
    const onboardingEl = document.getElementById('essentialOnboardingBanner');
    if (onboardingEl) onboardingEl.remove();
    
    // Restore user's active view upon reload or default to Account Hub on fresh session start
    if (!window._initialAuthRouted) {
      window._initialAuthRouted = true;
      const savedView = sessionStorage.getItem('activeView');
      const savedAdminTab = sessionStorage.getItem('activeAdminTab');
      const savedAccountTab = sessionStorage.getItem('activeAccountTab');
      const savedArg = sessionStorage.getItem('activeViewArg');

      if (savedView === 'admin' && views.admin) {
        views.admin(savedAdminTab || 'tab-tools');
      } else if (savedView === 'account' && views.account) {
        views.account(savedAccountTab || savedArg || 'Profile');
      } else if (savedView && typeof views[savedView] === 'function') {
        views[savedView](savedArg);
      } else if (views.account) {
        views.account();
      }
    } else {
      if (app.querySelector('#accountHubView')) views.account(); // Refresh account view if open
      else if (typeof window.activeViewFunc === 'function') window.activeViewFunc();
    }
  } else {
    window._initialAuthRouted = false;
    if(authSidebarBtn) authSidebarBtn.innerHTML = `🔐 Sign In / Register`;
    if(signOutSidebarBtn) signOutSidebarBtn.style.display = 'none';
    window.updateNavbarUserIndicator(null);
    
    if (app.querySelector('#accountHubView') || app.querySelector('#adminHubView')) views.home(); // Kick to home
  }
  
  checkMaintenanceAccess();
});

// Master Key Spoofing Methods
window.adminSpoofPlayer = async (spoofId) => {
    if (!realUser || !window.isAdminUser(realUser)) return;
    
    const isUnlocked = await window.isGoogleAuthVerified();
    if (!isUnlocked) {
        window.showToast("Security unlock required to use the master key. Please log in with Google.", "error");
        views.admin(); // Kick to admin screen for auth verification
        return;
    }
    
    if (!spoofId) return;
    
    // Fetch the spoofed user's actual linked accounts
    let spoofedLinks = [];
    try {
        const usersSnap = await get(ref(db, 'users'));
        if (usersSnap.exists()) {
            const users = usersSnap.val();
            for (const u of Object.values(users)) {
                if (Number(u.gameId) === Number(spoofId)) {
                    spoofedLinks = u.linkedGameIds || [];
                    break;
                }
            }
        }
    } catch (e) {
        console.warn("Failed to fetch spoofed alt accounts:", e);
    }
    
    window._spoofedUser = true;
    currentUser = {
        ...realUser,
        gameId: spoofId,
        email: realUser?.email || "BrianDivaCox@gmail.com",
        linkedGameIds: spoofedLinks // Overwrite the admin's linked accounts with the spoofed user's
    };
    
    if (window.showToast) window.showToast(`Now spoofing Game ID: ${spoofId}`, "success");
    
    // Show the floating clear button
    const clearBtn = document.getElementById('floatingSpoofControls');
    if (clearBtn) clearBtn.style.display = 'flex';
    
    // Trigger a fake auth update to redraw the UI
    listenToAuth.fakeUpdate ? listenToAuth.fakeUpdate(currentUser) : null;
    
    // Brute force redraw
    window.updateNavbarUserIndicator(currentUser);
    let name = (currentUser && currentUser.gameId && idToNameMap[currentUser.gameId]) || 'Unknown';
    if(authSidebarBtn) authSidebarBtn.innerHTML = `🎭 Spoofing: ${name}`;
    
    if (app.querySelector('#accountHubView')) views.account();
};

window.clearSpoof = () => {
    if (!window._spoofedUser) return;
    window._spoofedUser = false;
    currentUser = realUser;
    
    if (window.showToast) window.showToast("Master key deactivated. Returned to normal.", "success");
    
    const clearBtn = document.getElementById('floatingSpoofControls');
    if (clearBtn) clearBtn.style.display = 'none';
    
    // Brute force redraw
    window.updateNavbarUserIndicator(currentUser);
    if(authSidebarBtn) authSidebarBtn.innerHTML = `👤 Account Hub`;
    
    // Trigger fake auth update to restore real state
    listenToAuth.fakeUpdate ? listenToAuth.fakeUpdate(currentUser) : null;
    if (app.querySelector('#accountHubView')) views.account();
};

window.switchSpoofUser = () => {
    window.clearSpoof();
    setTimeout(() => {
        if (views.admin) views.admin();
        if (views.playerEditor) views.playerEditor();
    }, 100);
};

