window.setGatekeeperColor = function(hex, dec) {
  if (!window._gkEditorState) return;
  window._gkEditorState.colorHex = hex;
  window._gkEditorState.colorDec = dec;
  const previewCard = document.getElementById('discordPreviewCard');
  if (previewCard) previewCard.style.borderLeft = `4px solid ${hex}`;
  window.updateGatekeeperPreview();
};

window.buildGatekeeperReportPayload = function() {
  const s = window._gkEditorState;
  if (!s) return null;

  const ann = (document.getElementById('gkEditorAnnouncement')?.value || '').trim();
  const incRoster = document.getElementById('gkToggleRoster')?.checked !== false;
  const incSignups = document.getElementById('gkToggleSignups')?.checked !== false;
  const incPerks = document.getElementById('gkTogglePerks')?.checked !== false;
  const incMaintenance = document.getElementById('gkToggleMaintenance')?.checked !== false;
  const incBot = document.getElementById('gkToggleBot')?.checked !== false;

  let sections = [];

  if (ann) {
    sections.push(`📢 **ALLIANCE DIRECTIVE**\n${ann}`);
  }

  // Read directly from the editable textareas
  if (incRoster) {
    const txt = document.getElementById('gkTextRoster')?.value || s.defaultSectionTexts?.roster || '';
    sections.push(txt.trim());
  }

  if (incSignups) {
    const txt = document.getElementById('gkTextSignups')?.value || s.defaultSectionTexts?.signups || '';
    sections.push(txt.trim());
  }

  if (incPerks) {
    const txt = document.getElementById('gkTextPerks')?.value || s.defaultSectionTexts?.perks || '';
    sections.push(txt.trim());
  }

  if (incMaintenance) {
    const txt = document.getElementById('gkTextMaintenance')?.value || s.defaultSectionTexts?.maintenance || '';
    sections.push(txt.trim());
  }

  if (incBot) {
    const txt = document.getElementById('gkTextBot')?.value || s.defaultSectionTexts?.bot || '';
    sections.push(txt.trim());
  }

  const description = sections.join('\n\n');

  return {
    content: "",
    embeds: [{
      title: s.title || "🏰 ALLIANCE GATEKEEPER REPORT",
      description: description || "No active sections selected.",
      color: s.colorDec || 3718648,
      footer: { text: s.footer || "Alliance Gatekeeper • Real-Time Live Sync ⚡" },
      timestamp: new Date().toISOString()
    }]
  };
};

window.updateGatekeeperPreview = function() {
  const payload = window.buildGatekeeperReportPayload();
  if (!payload) return;
  const descEl = document.getElementById('discordPreviewDesc');
  const titleEl = document.getElementById('discordPreviewTitle');
  if (titleEl) titleEl.textContent = payload.embeds[0].title;
  if (descEl) descEl.textContent = payload.embeds[0].description;
};

window.saveGatekeeperDraftSettings = async function() {
  const ann = (document.getElementById('gkEditorAnnouncement')?.value || '').trim();
  const incRoster = document.getElementById('gkToggleRoster')?.checked !== false;
  const incSignups = document.getElementById('gkToggleSignups')?.checked !== false;
  const incPerks = document.getElementById('gkTogglePerks')?.checked !== false;
  const incMaintenance = document.getElementById('gkToggleMaintenance')?.checked !== false;
  const incBot = document.getElementById('gkToggleBot')?.checked !== false;

  const data = {
    announcement: ann,
    incRoster,
    incSignups,
    incPerks,
    incMaintenance,
    incBot,
    useManualTextOverrides: false,
    colorHex: window._gkEditorState?.colorHex || "#38bdf8",
    colorDec: window._gkEditorState?.colorDec || 3718648,
    updatedAt: new Date().toISOString()
  };

  try {
    await set(ref(db, 'config/gatekeeperReportSettings'), data);
    if (window.showToast) window.showToast("💾 Gatekeeper report settings saved (Live Auto-Sync Active)!", "success");
  } catch(e) {
    if (window.showToast) window.showToast("Failed to save settings: " + e.message, "error");
  }
};

window.publishGatekeeperReportFromEditor = async function(btnEl) {
  const payload = window.buildGatekeeperReportPayload();
  if (!payload) return;

  let origText = '';
  if (btnEl) {
    origText = btnEl.innerHTML;
    btnEl.disabled = true;
    btnEl.innerHTML = '⏳ Updating Discord...';
  }

  try {
    await window.pushGatekeeperReportToDiscord(null, payload);
    await window.saveGatekeeperDraftSettings();
    if (window.showToast) window.showToast("🚀 Master Alliance Gatekeeper Report published to #alerts!", "success");
    const m = document.getElementById('gatekeeperReportModal');
    if (m) m.remove();
  } catch(e) {
    if (window.showToast) window.showToast("Failed to publish report: " + e.message, "error");
  } finally {
    if (btnEl) {
      btnEl.disabled = false;
      btnEl.innerHTML = origText;
    }
  }
};

window.openAltVerifyModal = (gid, altName = '') => {
  if (!currentUser) return;
  const cleanGid = (gid || '').toString().trim();
  const cleanName = (altName && !altName.startsWith('Game ID:')) 
    ? altName 
    : ((window.idToNameMap && window.idToNameMap[cleanGid]) || (currentUser.altTokens && currentUser.altTokens[cleanGid]?.nickname) || `Alt Chief (${cleanGid})`);

  const oldModal = document.getElementById('altVerifyModalOverlay');
  if (oldModal && oldModal.parentNode) oldModal.parentNode.removeChild(oldModal);

  const modalOverlay = document.createElement('div');
  modalOverlay.id = 'altVerifyModalOverlay';
  modalOverlay.style.cssText = 'position:fixed; inset:0; background:rgba(15,23,42,0.85); backdrop-filter:blur(10px); z-index:99999; display:flex; align-items:center; justify-content:center; animation:fadeIn 0.2s ease;';

  modalOverlay.innerHTML = `
    <div class="card" style="width:92%; max-width:440px; background:linear-gradient(145deg, rgba(15,23,42,0.96), rgba(30,41,59,0.94)); border:1px solid rgba(56,189,248,0.35); padding:24px; border-radius:20px; box-shadow:0 25px 60px rgba(0,0,0,0.7); text-align:left; animation:zoomIn 0.2s forwards; color:var(--text-main);">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px; border-bottom:1px solid rgba(255,255,255,0.08); padding-bottom:12px;">
        <h3 style="margin:0; color:#fff; font-size:18px; font-weight:bold; display:flex; align-items:center; gap:8px;">
          🛡️ 30-Day Sync for ${window.escapeHTML(cleanName)}
        </h3>
        <button onclick="document.getElementById('altVerifyModalOverlay').remove()" style="background:none; border:none; color:var(--text-muted); font-size:26px; cursor:pointer; line-height:1;">&times;</button>
      </div>

      <p style="font-size:13px; color:var(--text-muted); margin:0 0 16px 0; line-height:1.5;">
        Send a verification code to <strong>${window.escapeHTML(cleanName)}</strong> (Game ID: <strong>${window.escapeHTML(cleanGid)}</strong>) to bind a <strong>30-day automatic sync token</strong> for stats and in-game avatars.
      </p>

      <div style="text-align:center; margin-bottom:14px;">
        <button id="sendAltCodeBtn" style="background:linear-gradient(135deg, #0ea5e9, #0284c7); color:#fff; border:none; padding:10px 20px; border-radius:8px; font-weight:bold; font-size:14px; cursor:pointer; box-shadow:0 2px 10px rgba(14,165,233,0.3); width:100%;">
          📩 Send Code to In-Game Mail
        </button>
      </div>

      <div id="altVerifyCodeSection" style="background:rgba(255,255,255,0.03); border:1px solid rgba(56,189,248,0.3); border-radius:12px; padding:14px; margin-bottom:14px;">
        <label style="display:block; font-size:12px; font-weight:bold; color:#38bdf8; margin-bottom:6px; text-transform:uppercase;">
          🔑 Enter 6-Digit In-Game Code
        </label>
        <p style="font-size:11.5px; color:var(--text-muted); margin:0 0 10px 0;">
          Check <strong>${window.escapeHTML(cleanName)}</strong>'s in-game system mail for the code, or enter any active code from today:
        </p>
        <div style="display:flex; gap:8px;">
          <input type="text" id="altCaptchaInput" maxlength="8" placeholder="e.g. 123456" style="flex:1; padding:10px 12px; border-radius:8px; border:1px solid var(--border); background:var(--bg-main); color:#fff; font-size:16px; font-family:monospace; letter-spacing:3px; text-align:center; font-weight:bold;">
          <button id="submitAltCodeBtn" style="background:linear-gradient(135deg, #10b981, #059669); color:#fff; border:none; padding:10px 18px; border-radius:8px; font-weight:bold; font-size:13.5px; cursor:pointer; flex-shrink:0;">
            Verify & Bind
          </button>
        </div>
        <div id="altVerifyFeedback" style="font-size:12px; margin-top:8px; display:none;"></div>
      </div>

      <div style="display:flex; justify-content:flex-end;">
        <button onclick="document.getElementById('altVerifyModalOverlay').remove()" style="background:rgba(255,255,255,0.08); border:1px solid rgba(255,255,255,0.15); color:#cbd5e1; padding:8px 16px; border-radius:8px; cursor:pointer; font-size:13px;">
          Cancel
        </button>
      </div>
    </div>
  `;

  document.body.appendChild(modalOverlay);

  const sendBtn = document.getElementById('sendAltCodeBtn');
  const codeSection = document.getElementById('altVerifyCodeSection');
  const submitCodeBtn = document.getElementById('submitAltCodeBtn');
  const codeInput = document.getElementById('altCaptchaInput');
  const feedback = document.getElementById('altVerifyFeedback');

  if (sendBtn) {
    sendBtn.addEventListener('click', async () => {
      sendBtn.disabled = true;
      sendBtn.textContent = 'Sending Code...';
      try {
        const data = await window.apiSendGameCaptcha(cleanGid);
        if (data && (data.success || data.code === 0 || data.code === 1)) {
          sendBtn.textContent = '🔄 Resend Code';
          sendBtn.disabled = false;
          if (codeSection) codeSection.style.display = 'block';
          if (feedback) {
            feedback.style.display = 'block';
            feedback.style.color = '#38bdf8';
            feedback.textContent = 'Code dispatched! Check your Whiteout Survival system mail.';
          }
          window.showToast(`📩 Verification code sent to ${cleanName}'s mail!`, 'info');
          if (codeInput) setTimeout(() => codeInput.focus(), 60);
        } else {
          throw new Error(window.translateWosApiError(data?.message || 'Failed to dispatch in-game code.', data?.code));
        }
      } catch (err) {
        sendBtn.disabled = false;
        sendBtn.textContent = '📩 Send Code to In-Game Mail';
        const msg = window.translateWosApiError(err.message || 'Error communicating with game servers.');
        if (feedback) {
          feedback.style.display = 'block';
          feedback.style.color = 'var(--danger)';
          feedback.textContent = msg;
        }
        window.showToast(msg, 'error');
      }
    });
  }

  if (submitCodeBtn && codeInput) {
    const handleVerify = async () => {
      const code = codeInput.value.trim();
      if (!code || code.length < 4) {
        if (feedback) {
          feedback.style.display = 'block';
          feedback.style.color = 'var(--danger)';
          feedback.textContent = 'Please enter valid 6-digit code.';
        }
        return;
      }

      submitCodeBtn.disabled = true;
      submitCodeBtn.textContent = 'Verifying...';
      if (feedback) feedback.style.display = 'none';

      try {
        const savedPrimaryGid = (currentUser.gameId || '').toString().trim();
        const savedPrimaryName = (currentUser.name || '').toString().trim();
        const savedPrimaryStove = (currentUser.stove_lv || currentUser.furnaceLevel || '').toString().trim();
        const savedPrimaryAvatar = (currentUser.avatar_image || '').toString().trim();
        const savedPrimaryToken = (currentUser.wos_cg_token || '').toString().trim();

        const data = await window.apiVerifyGameCaptcha(cleanGid, code);

        if (data && (data.success || data.token) && (data.token || data.data?.token)) {
          const nowIso = new Date().toISOString();
          const altChiefName = data.nickname || cleanName;
          const altTokenObj = {
            token: data.token,
            section: data.section || "2089",
            stove_lv: data.stove_lv || "",
            nickname: altChiefName,
            avatar_image: data.avatar_image || "",
            tokenExpired: false,
            tokenStatus: {
              status: 'active',
              daysLeft: 30,
              verifiedAt: nowIso
            },
            verifiedAt: nowIso,
            lastSyncedAt: nowIso,
            centuryGamesVerified: true
          };

          await update(ref(db, `users/${currentUser.uid}/altTokens/${cleanGid}`), altTokenObj);
          if (!currentUser.altTokens) currentUser.altTokens = {};
          currentUser.altTokens[cleanGid] = altTokenObj;

          const altUpdates = {
            stove_lv: data.stove_lv || "",
            section: data.section || "2089",
            lastSyncedAt: nowIso,
            centuryGamesVerified: true
          };
          if (data.avatar_image) {
            altUpdates.avatar_image = data.avatar_image;
            try {
              await uploadAvatar(cleanGid, data.avatar_image);
              avatarMap[cleanGid] = data.avatar_image;
            } catch(e) {}
          }
          if (data.nickname && !/^\d+$/.test(data.nickname)) altUpdates.name = data.nickname;
          await update(ref(db, `users_alts/${cleanGid}`), altUpdates);

          // Guarantee main profile memory isolation
          if (savedPrimaryGid) currentUser.gameId = savedPrimaryGid;
          if (savedPrimaryName) currentUser.name = savedPrimaryName;
          if (savedPrimaryStove) {
            currentUser.stove_lv = savedPrimaryStove;
            currentUser.furnaceLevel = savedPrimaryStove;
          }
          if (savedPrimaryAvatar) currentUser.avatar_image = savedPrimaryAvatar;
          if (savedPrimaryToken) currentUser.wos_cg_token = savedPrimaryToken;
          try { localStorage.setItem('cached_current_user', JSON.stringify(currentUser)); } catch(e) {}

          modalOverlay.remove();
          window.showToast(`🎉 30-Day sync token bound for ${data.nickname || cleanName}!`, 'success');
          if (views.account) views.account('Alts');
        } else {
          throw new Error(window.translateWosApiError(data.message || 'Invalid or expired code.', data.code));
        }
      } catch (err) {
        submitCodeBtn.disabled = false;
        submitCodeBtn.textContent = 'Verify & Bind';
        const msg = window.translateWosApiError(err.message || 'Verification failed.');
        if (feedback) {
          feedback.style.display = 'block';
          feedback.style.color = 'var(--danger)';
          feedback.textContent = msg;
        }
        window.showToast(msg, 'error');
      }
    };

    submitCodeBtn.addEventListener('click', handleVerify);
    codeInput.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleVerify();
      }
    });
  }
};

window.openEditAltProfileModal = async (gameId, chiefName) => {
   if (!currentUser) return;
   const cleanGid = (gameId || '').toString().trim();
   const resolvedChiefName = chiefName || (window.idToNameMap && window.idToNameMap[cleanGid]) || (currentUser.altTokens && currentUser.altTokens[cleanGid]?.nickname) || `Alt Chief ${cleanGid}`;

   let currentFurnace = '';
   let currentJoinedDate = '';

   // 1. Check currentUser.linkedAltsData first
   if (currentUser.linkedAltsData && currentUser.linkedAltsData[cleanGid]) {
      const savedAlt = currentUser.linkedAltsData[cleanGid];
      currentFurnace = savedAlt.stove_lv || savedAlt.furnaceLevel || '';
      currentJoinedDate = savedAlt.joinedDate || '';
   }

   // 2. Fallback to users_alts
   if (!currentFurnace || !currentJoinedDate) {
      try {
         const altSnap = await get(ref(db, `users_alts/${cleanGid}`));
         if (altSnap.exists()) {
            const altData = altSnap.val();
            if (!currentFurnace) currentFurnace = altData.stove_lv || altData.furnaceLevel || '';
            if (!currentJoinedDate) currentJoinedDate = altData.joinedDate || '';
         }
      } catch(e) {}
   }

   // 3. Fallback to roster_live
   if (!currentFurnace || !currentJoinedDate) {
      try {
         const rosterSnap = await get(ref(db, 'roster_live'));
         if (rosterSnap.exists()) {
            const roster = rosterSnap.val() || {};
            const rItem = roster[cleanGid] || roster[resolvedChiefName] || Object.values(roster).find(r => r.gameId === cleanGid || (r.name && r.name.toLowerCase() === resolvedChiefName.toLowerCase()));
            if (rItem) {
               if (!currentFurnace) currentFurnace = rItem.furnaceLevel || rItem.stove_lv || '';
               if (!currentJoinedDate) currentJoinedDate = rItem.joinedDate || '';
            }
         }
      } catch(e) {}
   }

   // 4. Fallback to altToken metadata & avatar image timestamp
   if (!currentJoinedDate) {
      const altToken = currentUser.altTokens && currentUser.altTokens[cleanGid];
      const avUrl = (altToken && altToken.avatar_image) || '';
      const m = avUrl.match(/\/avatar\/(\d{4})\/(\d{2})\/(\d{2})\//);
      if (m) {
         currentJoinedDate = `${m[1]}-${m[2]}-${m[3]}`;
      } else if (altToken && altToken.verifiedAt) {
         try {
            currentJoinedDate = new Date(altToken.verifiedAt).toISOString().split('T')[0];
         } catch(e) {}
      }
   }

   const initialTimeActive = currentJoinedDate ? window.calculateTimeActive(currentJoinedDate) : 'Unknown';
   const formattedInputDate = window.formatDateForInput(currentJoinedDate);

   const modalOverlay = document.createElement('div');
   modalOverlay.id = 'editAltProfileModalOverlay';
   modalOverlay.style.cssText = 'position:fixed; inset:0; z-index:999999; background:rgba(0,0,0,0.75); backdrop-filter:blur(8px); display:flex; align-items:center; justify-content:center; padding:20px; animation:fadeIn 0.2s ease;';

   const furnaceSelectHtml = window.renderFurnaceSelectHtml('editAltFurnaceSelect', currentFurnace, 'margin-top:6px;');

   modalOverlay.innerHTML = `
     <div style="background:var(--card-bg); border:1px solid var(--border); border-radius:20px; width:100%; max-width:480px; padding:28px; box-shadow:0 25px 50px -12px rgba(0,0,0,0.7); position:relative;">
        <button id="closeEditAltProfileBtn" style="position:absolute; top:18px; right:18px; background:transparent; border:none; color:var(--text-muted); font-size:20px; cursor:pointer; font-weight:bold; width:32px; height:32px; border-radius:50%; display:flex; align-items:center; justify-content:center;">✕</button>

        <h3 style="margin:0 0 6px 0; color:var(--text-main); font-size:20px; font-weight:bold; display:flex; align-items:center; gap:8px;">
           ✏️ Edit Alt Profile: <span style="color:var(--accent);">${window.escapeHTML(chiefName)}</span>
        </h3>
        <div style="font-size:13px; color:var(--text-muted); margin-bottom:20px;">Game ID: ${cleanGid}</div>

        <div style="display:flex; flex-direction:column; gap:18px;">
           
           <!-- Preview Card -->
           <div style="background:rgba(15,23,42,0.7); border:1px solid rgba(255,255,255,0.1); border-radius:16px; padding:16px 20px; display:flex; align-items:center; justify-content:flex-start; gap:20px;">
              <div id="editAltBadgePreview" style="min-width:60px; height:52px; display:inline-flex; align-items:center; justify-content:center; flex-shrink:0;">
                 ${window.getFurnaceIconHtml(currentFurnace, 52)}
              </div>
              <div style="display:flex; flex-direction:column; min-width:0;">
                 <span style="font-size:16px; font-weight:bold; color:#fff; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${window.escapeHTML(chiefName)}</span>
                 <span id="editAltTimeActivePreview" style="font-size:13px; color:#06b6d4; font-weight:bold; margin-top:4px; display:flex; align-items:center; gap:4px;">⏱️ ${initialTimeActive}</span>
              </div>
           </div>

           <!-- Furnace Level Input -->
           <div>
              <label style="font-size:13px; font-weight:bold; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.5px;">🔥 Furnace / Fire Crystal Level</label>
              ${furnaceSelectHtml}
           </div>

           <!-- Start Date Input -->
           <div>
              <label style="font-size:13px; font-weight:bold; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.5px;">📅 Account Start Date (Joined Date)</label>
              <input type="date" id="editAltJoinedDateInput" value="${formattedInputDate}" style="width:100%; padding:10px 14px; border-radius:8px; border:1px solid var(--border); background:var(--bg-main); color:var(--text-main); font-size:15px; margin-top:6px; box-sizing:border-box;">
              <div style="font-size:11px; color:var(--text-muted); margin-top:4px;">Setting the start date automatically computes your Alt's exact Time Active.</div>
           </div>

           <div style="display:flex; gap:12px; margin-top:10px;">
              <button id="cancelEditAltProfileBtn" style="flex:1; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.2); color:#cbd5e1; padding:12px; border-radius:10px; cursor:pointer; font-weight:bold; font-size:15px;">Cancel</button>
              <button id="saveEditAltProfileBtn" style="flex:1; background:linear-gradient(135deg, #06b6d4, #3b82f6); color:#fff; border:none; padding:12px; border-radius:10px; cursor:pointer; font-weight:bold; font-size:15px; box-shadow:0 4px 15px rgba(6,182,212,0.4);">Save Changes</button>
           </div>
        </div>
     </div>`;

   document.body.appendChild(modalOverlay);

   const fSelect = document.getElementById('editAltFurnaceSelect');
   const dInput = document.getElementById('editAltJoinedDateInput');
   const bPreview = document.getElementById('editAltBadgePreview');
   const taPreview = document.getElementById('editAltTimeActivePreview');

   const updatePreviews = () => {
      if (fSelect && bPreview) {
         bPreview.innerHTML = window.getFurnaceIconHtml(fSelect.value, 52);
      }
      if (dInput && taPreview) {
         const calculated = window.calculateTimeActive(dInput.value);
         taPreview.textContent = `⏱️ ${calculated}`;
      }
   };

   if (fSelect) fSelect.addEventListener('change', updatePreviews);
   if (dInput) {
      dInput.addEventListener('input', updatePreviews);
      dInput.addEventListener('change', updatePreviews);
   }

   const closeModal = () => { if (document.body.contains(modalOverlay)) document.body.removeChild(modalOverlay); };
   const closeBtn = document.getElementById('closeEditAltProfileBtn');
   const cancelBtn = document.getElementById('cancelEditAltProfileBtn');
   if (closeBtn) closeBtn.onclick = closeModal;
   if (cancelBtn) cancelBtn.onclick = closeModal;

   const saveBtn = document.getElementById('saveEditAltProfileBtn');
   if (saveBtn) {
      saveBtn.onclick = async () => {
         const newFurnace = fSelect ? fSelect.value : currentFurnace;
         const newJoinedDate = dInput ? dInput.value : currentJoinedDate;
         const calculatedTimeActive = window.calculateTimeActive(newJoinedDate);

         saveBtn.disabled = true;
         saveBtn.textContent = 'Saving...';

         try {
            // 1. Save to users/${currentUser.uid}/linkedAltsData/${cleanGid} in Firebase
            if (currentUser && currentUser.uid) {
               await update(ref(db, `users/${currentUser.uid}/linkedAltsData/${cleanGid}`), {
                  gameId: cleanGid,
                  name: chiefName,
                  stove_lv: newFurnace,
                  furnaceLevel: newFurnace,
                  joinedDate: newJoinedDate,
                  timeActive: calculatedTimeActive,
                  updatedAt: new Date().toISOString()
               }).catch(e => console.warn("linkedAltsData save error:", e));

               if (currentUser.altTokens && currentUser.altTokens[cleanGid]) {
                  await update(ref(db, `users/${currentUser.uid}/altTokens/${cleanGid}`), {
                     stove_lv: newFurnace,
                     furnaceLevel: newFurnace,
                     nickname: chiefName
                  }).catch(() => null);
                  currentUser.altTokens[cleanGid].stove_lv = newFurnace;
                  currentUser.altTokens[cleanGid].furnaceLevel = newFurnace;
               }

               currentUser.linkedAltsData = currentUser.linkedAltsData || {};
               currentUser.linkedAltsData[cleanGid] = {
                  gameId: cleanGid,
                  name: chiefName,
                  stove_lv: newFurnace,
                  furnaceLevel: newFurnace,
                  joinedDate: newJoinedDate,
                  timeActive: calculatedTimeActive
               };
               try { localStorage.setItem('cached_current_user', JSON.stringify(currentUser)); } catch(e) {}
            }

            // 2. Save to users_alts/${cleanGid} in Firebase
            await set(ref(db, `users_alts/${cleanGid}`), {
               gameId: cleanGid,
               name: chiefName,
               stove_lv: newFurnace,
               furnaceLevel: newFurnace,
               joinedDate: newJoinedDate,
               timeActive: calculatedTimeActive,
               updatedAt: new Date().toISOString()
            }).catch(e => console.warn("users_alts save error:", e));

            // 3. Save to roster_live in Firebase safely
            try {
               const rosterSnap = await get(ref(db, 'roster_live')).catch(() => null);
               let rosterObj = (rosterSnap && rosterSnap.exists()) ? rosterSnap.val() : {};

               let foundKey = null;
               for (const [rk, rv] of Object.entries(rosterObj)) {
                  if (rk.toLowerCase() === chiefName.toLowerCase() ||
                     (rv && rv.name && rv.name.toLowerCase() === chiefName.toLowerCase()) ||
                     (cleanGid && rv && rv.gameId && rv.gameId.toString().trim() === cleanGid)) {
                     foundKey = rk;
                     break;
                  }
               }
               const saveKey = foundKey || cleanGid;
               rosterObj[saveKey] = {
                  ...(rosterObj[saveKey] || {}),
                  name: chiefName,
                  gameId: cleanGid,
                  furnaceLevel: newFurnace,
                  stove_lv: newFurnace,
                  joinedDate: newJoinedDate,
                  timeActive: calculatedTimeActive,
                  updatedAt: Date.now()
               };

               await set(ref(db, `roster_live/${saveKey}`), rosterObj[saveKey]);
               if (cleanGid && cleanGid !== saveKey) {
                  await set(ref(db, `roster_live/${cleanGid}`), rosterObj[saveKey]);
               }
               window.rosterCache = rosterObj;
            } catch(e) { console.warn("roster_live alt save error:", e); }

            // 4. Update in-memory liveData Chief's List row if present
            if (window.liveData && window.liveData["Chief's List"]) {
               const cList = window.liveData["Chief's List"];
               for (let i = 1; i < cList.length; i++) {
                  if ((cleanGid && cList[i][1] && cList[i][1].toString().trim() === cleanGid) ||
                      (chiefName && cList[i][0] && cList[i][0].toString().toLowerCase().trim() === chiefName.toLowerCase())) {
                     cList[i][2] = newFurnace;
                     if (newJoinedDate) cList[i][4] = window.formatDateForDisplay(newJoinedDate);
                     break;
                  }
               }
            }

            // Sync with BDC Central Command Backend
            window.callBdcBackend('update_furnace', {
               gameId: cleanGid,
               name: chiefName,
               level: newFurnace,
               joinedDate: newJoinedDate
            }).catch(() => null);

            try {
               const token = await getAuthToken();
               const url = `${API_BASE_URL}?api=updateChiefLevel&gameId=${encodeURIComponent(cleanGid)}&name=${encodeURIComponent(chiefName)}&level=${encodeURIComponent(newFurnace)}&joinedDate=${encodeURIComponent(newJoinedDate)}&token=${encodeURIComponent(token)}`;
               fetch(url, { mode: 'no-cors' }).catch(e => null);
            } catch(e) {}

            // 5. Log Admin / Profile action with target Alt details
            if (window.logAdminAction) {
               window.logAdminAction(
                  "Alt Profile Update", 
                  `Updated Alt account '${chiefName}' (ID: ${cleanGid}) Furnace to ${newFurnace}${newJoinedDate ? `, Start Date to ${newJoinedDate}` : ''}`, 
                  chiefName
               );
            }

            window.showToast(`Updated alt profile for ${chiefName}!`, "success");
            closeModal();
            if (views.account) views.account('Alts');
         } catch(e) {
            console.error("Save alt profile error:", e);
            window.showToast("Error updating alt profile.", "error");
            saveBtn.disabled = false;
            saveBtn.textContent = 'Save Changes';
         }
      };
   }
};

window.parseScheduleEventDate = (dateStr) => {
  if (!dateStr) return null;
  const s = String(dateStr).trim();
  const now = new Date();
  
  // 1. Check for explicit M/D e.g. 8/22 or 08/22
  const mdMatch = s.match(/(\d{1,2})\/(\d{1,2})/);
  if (mdMatch) {
    return new Date(now.getFullYear(), parseInt(mdMatch[1]) - 1, parseInt(mdMatch[2]));
  }
  
  // 2. Check for YYYY-MM-DD
  const isoMatch = s.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    return new Date(parseInt(isoMatch[1]), parseInt(isoMatch[2]) - 1, parseInt(isoMatch[3]));
  }

  // 3. Check for Month name + Day e.g. "Aug 22" or "August 22"
  const monthMatch = s.match(/(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s*(\d{1,2})/i);
  if (monthMatch) {
    const months = { jan:0, feb:1, mar:2, apr:3, may:4, jun:5, jul:6, aug:7, sep:8, oct:9, nov:10, dec:11 };
    const mIdx = months[monthMatch[1].toLowerCase().slice(0, 3)];
    if (mIdx !== undefined) {
      return new Date(now.getFullYear(), mIdx, parseInt(monthMatch[2]));
    }
  }

  // 4. Check for Day of Week e.g. "Saturday", "Sat"
  const daysMap = { sunday:0, sun:0, monday:1, mon:1, tuesday:2, tue:2, wednesday:3, wed:3, thursday:4, thu:4, friday:5, fri:5, saturday:6, sat:6 };
  const lower = s.toLowerCase();
  for (const [dayName, dayNum] of Object.entries(daysMap)) {
    if (lower.includes(dayName)) {
      const currentDay = now.getDay();
      let diff = dayNum - currentDay;
      if (diff < 0) diff += 7;
      const target = new Date(now);
      target.setDate(now.getDate() + diff);
      target.setHours(0, 0, 0, 0);
      return target;
    }
  }

  return null;
};

window.parseScheduleEventTime = (timeStr, pdtVal) => {
  if (!timeStr && !pdtVal) return null;
  const s = String(timeStr || '').trim();
  
  // 1. Direct HH:mm (e.g. "19:00", "07:30", "19:00 UTC")
  const hmMatch = s.match(/^(\d{1,2}):(\d{2})(?:\s*UTC)?$/i);
  if (hmMatch) {
    return { h: parseInt(hmMatch[1]), m: parseInt(hmMatch[2]) };
  }

  // 2. ISO timestamp from GAS: e.g. 1899-12-30T20:00:00.000Z
  if (s.includes('T') && s.includes('Z')) {
    const d = new Date(s);
    if (!isNaN(d.getTime())) {
      return { h: d.getUTCHours(), m: d.getUTCMinutes() };
    }
  }

  // 3. 12-hour format e.g. '5:00 AM', '9:30 PM', '12:00 PM PDT'
  const targetStr = String(pdtVal || s);
  const pdtMatch = targetStr.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)/i);
  if (pdtMatch) {
    let h = parseInt(pdtMatch[1]);
    const m = parseInt(pdtMatch[2]);
    const isPM = pdtMatch[3].toUpperCase() === 'PM';
    if (isPM && h < 12) h += 12;
    if (!isPM && h === 12) h = 0;
    // If from pdtVal, convert PDT (UTC-7) to UTC (+7 hours)
    if (pdtVal && targetStr === pdtVal) {
      return { h: (h + 7) % 24, m };
    }
    return { h, m };
  }

  return null;
};

